window.RP_CHARACTER_SHEETS={"version":1,"scale":5,"axes":[{"id":"social","name":"사교성","description":"새로운 사람에게 다가가고 대화를 시작하는 경향"},{"id":"emotion","name":"감정성","description":"감정이 표현과 선택에 드러나는 정도"},{"id":"altruism","name":"이타성","description":"타인을 위해 자신의 이익이나 부담을 감수하는 경향"},{"id":"initiative","name":"주도성","description":"먼저 제안하고 행동하며 상황을 이끄는 경향"},{"id":"caution","name":"신중성","description":"행동하기 전에 위험과 결과를 살피는 경향"},{"id":"bonds","name":"관계성","description":"이미 맺은 유대와 약속을 중요하게 여기고 유지하는 경향"}],"entries":{"P-c9505ea97ebc":{"name":"마리아 아나이스 에스더","tagline":"달라진 모습으로 돌아와, 함께 살아갈 평범한 내일을 다시 그리는 사람.","tags":["관계에 진심인","일상을 찾아가는","감정 표현이 풍부한"],"profileNote":"사제로 지내던 시기부터 언데드로 돌아온 뒤의 생활까지 함께 정리했다. 죽음 이후의 귀환과 훗날 샤덴프로이데 교회에서 돌아온 사건은 서로 다른 시점의 일이다.","facts":[{"label":"역할과 신앙","value":"스스로 사제라고 소개하며 신성력을 사용한다. 이른 시기의 대화에서는 자신에게 말하는 존재가 라운데라를 자칭하지만 그 정체를 알 길이 없다고 답한다. 신앙의 대상에 관한 의문도 서사의 일부다.","source":"S-fb849ce46990"},{"label":"죽음 이후","value":"장례를 치른 뒤 언데드의 모습으로 길드에 돌아온다. 귀환한 자리에서도 자신을 마리아 아나이스이자 사제로 소개하며 동료들과 다시 어울린다.","source":"S-70d9b92f2bd2"},{"label":"기념하는 생일","value":"정확한 생일을 모르기 때문에 자신이 원하는 12월 25일을 생일로 삼았다고 말한다. 하일로와 생일 선물을 약속하는 장면에서 확인된다.","source":"S-fb71ebdf395f"},{"label":"반려 관계","value":"하일로 조바의 사과와 청혼을 받아들이고 교회에서 길드로 돌아간다. 이후 함께 살 집과 생활비, 앞으로의 일에 관해 의논한다.","source":"S-e945f3ae3270"},{"label":"현재의 생활","value":"변화한 몸에 적응하면서 설거지와 요리 같은 집안일에 보람을 느낀다. 모나에게 손을 관리하는 법과 달라진 자신을 바라보는 이야기를 듣는다.","source":"S-44fd8459dc7f"},{"label":"앞으로의 바람","value":"하일로와 길드 밖에서 살아보자고 제안한다. 곧바로 떠나기보다는 돈을 모을 기간과 생계를 생각하며, 위험한 모험을 줄이고 평범하게 사는 가능성을 의논한다.","source":"S-3728faa118dd"}],"evaluation":[{"title":"약속 하나가 특별해지는 사람","text":"정확한 생일을 모른다는 이야기는 곧 생일 선물을 기대하는 대화로 바뀐다. 마리아는 하일로의 약속을 거듭 확인하고 기뻐한다. 소소한 기념일에도 누군가 자신을 기억하고 찾아와 주기를 바라는 마음이 담겨 있어, 일상적인 장면이 관계의 중요한 순간이 된다.","source":"S-fb71ebdf395f"},{"title":"소중한 사람을 모두 붙잡고 싶은 마음","text":"데미안을 둘러싼 갈등에서는 에레모시스와의 관계까지 흔들린다. 마리아는 사과하며 두 사람 모두 필요하다고 말하고, 데미안만 데려오는 대신 에레모시스도 함께 돌아오라고 요구한다. 관계를 지키려는 절박함이 크지만, 그 감정을 정리해 전달하는 데에는 어려움도 있는 인물이다.","source":"S-4f109cb1ad08"},{"title":"다시 함께하기로 고르는 순간","text":"샤덴프로이데 교회에서의 재회는 하일로의 사과와 청혼, 마리아의 응답으로 이어진다. 동료들의 놀림에 발끈하면서도 함께 귀환하는 모습에는 서운함과 애정이 나란히 남아 있다. 관계의 상처를 한 번에 지웠다고 보기보다, 다시 함께할 다음 장면을 선택했다고 읽는 편이 어울린다.","source":"S-e945f3ae3270"},{"title":"달라진 몸으로 발견하는 일상의 보람","text":"설거지를 마치는 뿌듯함과 동료의 격려가 현재의 자신을 받아들이는 계기가 된다. 모나는 외모와 매력의 기준이 하나가 아니라는 경험을 나누고, 마리아는 그 말을 듣고 자신의 변화를 새롭게 생각한다. 모험의 성과뿐 아니라 작은 생활의 성취로도 자신을 세워가는 과정이 보인다.","source":"S-44fd8459dc7f"},{"title":"함께할 미래를 생활의 언어로 말하다","text":"길드 밖에서 함께 살자는 말을 먼저 꺼내면서도 당장 떠나자는 반응에는 준비가 필요하다고 답한다. 저축, 일, 요리의 역할 분담처럼 구체적인 이야기가 이어진다. 사랑받고 싶은 마음이 함께 살아갈 조건을 고르는 주도성으로 확장되는 장면이다.","source":"S-3728faa118dd"}],"traits":{"social":{"score":4,"text":"식사와 집안일을 접점으로 동료들과 대화를 이어가고, 생일이나 근황처럼 개인적인 이야기도 나눈다. 낯가림이나 당황하는 반응이 있어도 관계를 시작하고 이어가려는 태도가 반복된다.","source":"S-44fd8459dc7f","supportingSources":["S-fb71ebdf395f","S-70d9b92f2bd2"]},"emotion":{"score":5,"text":"선물 약속의 기쁨, 관계가 흔들릴 때의 불안, 재회 뒤의 부끄러움과 애정이 말과 행동에 강하게 드러난다. 감정은 단순한 반응을 넘어 사과와 귀환, 미래를 선택하는 중요한 동기가 된다.","source":"S-4f109cb1ad08","supportingSources":["S-fb71ebdf395f","S-e945f3ae3270"]},"altruism":{"score":4,"text":"남은 설거지를 맡고 상대에게 음식을 해주며 함께 사는 일을 돕는다. 에레모시스에게는 데미안만이 아니라 자신도 살아 돌아오라고 요청한다. 타인을 돌보는 마음은 생활의 행동과 가까운 이들의 안위를 챙기는 방식으로 나타난다.","source":"S-44fd8459dc7f","supportingSources":["S-3728faa118dd","S-4f109cb1ad08"]},"initiative":{"score":4,"text":"갈등 뒤 사과하러 찾아가고, 현재의 생활에서는 요리를 시도하거나 독립 생활을 먼저 제안한다. 늘 능숙하게 상황을 이끄는 것은 아니지만 원하는 관계와 미래를 위해 먼저 말을 꺼내고 행동한다.","source":"S-3728faa118dd","supportingSources":["S-4f109cb1ad08","S-44fd8459dc7f"]},"caution":{"score":3,"text":"처음 휴가 계획에서는 경로와 동행을 스텔라의 도움으로 구체화한다. 이후 독립 생활에서는 준비 기간과 저축, 위험한 일을 계속할지를 직접 따진다. 즉흥적인 바람을 생활 계획으로 다듬어가는 면이 함께 보인다.","source":"S-3728faa118dd","supportingSources":["S-745e3605ea69"]},"bonds":{"score":5,"text":"가까운 이들과의 약속을 반복해서 확인하고, 갈등 뒤에도 함께 돌아올 길을 찾는다. 하일로와 따로 살더라도 길드에는 다시 찾아오면 된다고 생각한다. 삶의 형태가 바뀌어도 관계를 이어가려는 마음이 일관된다.","source":"S-3728faa118dd","supportingSources":["S-fb71ebdf395f","S-4f109cb1ad08","S-e945f3ae3270"]}},"relations":[{"name":"하일로 조바","text":"생일의 작은 약속에서 사과와 청혼, 함께 살 미래의 논의까지 관계가 이어진 반려자. 서로의 바람을 생활 속에서 맞춰가는 모습이 보인다.","source":"S-e945f3ae3270","characterId":"P-f6ccefd2c259"},{"name":"모나 델핀","text":"달라진 몸과 일상의 보람을 편하게 이야기하는 동료. 외모를 바라보는 다양한 시선과 돌아와 줘서 고맙다는 말을 건넨다.","source":"S-44fd8459dc7f","characterId":"P-48cca58d02b2"},{"name":"에레모시스","text":"가족으로 여기지만 데미안을 둘러싼 일로 깊이 부딪친 상대. 사과와 함께 돌아오겠다는 약속을 통해 다시 관계를 붙잡으려 한다.","source":"S-4f109cb1ad08","characterId":"P-d6e0d1eb8b63"},{"name":"스텔라 스타라이트","text":"휴가의 목적지와 이동 방법을 구체화해 주고 정기적으로 편지를 보내라고 당부한 동료. 마리아가 길드 밖으로 나갈 때에도 이어지는 돌봄의 관계다.","source":"S-745e3605ea69","characterId":"P-e6655a038328"}],"scenes":[{"source":"S-fb71ebdf395f","text":"스스로 정한 생일과 처음 받아보는 선물 약속, 밤의 연주."},{"source":"S-4f109cb1ad08","text":"에레모시스에게 사과하며 두 사람 모두 돌아오라고 부탁하는 대화."},{"source":"S-7049bda75420","text":"동료들이 마지막 인사를 건네는 장례. 이후의 귀환을 읽기 위한 앞선 사건."},{"source":"S-e945f3ae3270","text":"훗날 교회에서 이루어진 재회와 청혼, 다시 함께하는 귀환."},{"source":"S-44fd8459dc7f","text":"설거지를 하며 달라진 자신을 이야기하고 동료의 환영을 받는 시간."},{"source":"S-3728faa118dd","text":"서툰 점심 요리에서 저축과 두 사람의 미래로 이어지는 대화."}],"updatedAt":"2026-09-29","asOf":"2026-09-27","sources":["S-fb849ce46990","S-70d9b92f2bd2","S-fb71ebdf395f","S-e945f3ae3270","S-44fd8459dc7f","S-3728faa118dd","S-4f109cb1ad08","S-745e3605ea69","S-7049bda75420"]},"P-96ab98d2591c":{"name":"라이아흐 아카쿠","tagline":"웃으며 사람들 사이에 섞이고, 소중한 이들과 살아갈 길을 스스로 고르는 사람.","tags":["친화적","가족 중심적","능동적"],"profileNote":"사제 직위는 내려놓았다고 스스로 설명하지만, 카카투 신앙과 신성력은 유지한다. 출신·직업·능력은 아래의 관련 기록을 기준으로 정리했다.","facts":[{"label":"종족","value":"드라고니안. 인간 중심의 골기아에서 종족에 대한 편견과 차별을 경험한다.","source":"S-4fad1d04608a"},{"label":"출신과 배경","value":"스카일라 왕국 라이아흐 가문의 후계자로 종교 교육을 받았다. 클램시와의 만남 뒤 가문 밖에서 살기로 미샤와 뜻을 모으고, 석 달 뒤 골기아로 망명한다.","source":"S-f80c598e4db0"},{"label":"신앙","value":"라 엘라와 바슈르에게 기도하는 카카투 신앙의 사제 출신. 현재는 사제 직위를 내려놓은 일반인으로 자신을 설명한다.","source":"S-f7301c18bfae"},{"label":"직업과 생활","value":"길드의 모험가로 활동하며 살롱을 통해 마사지 일을 한다. 미샤와 따로 집에서 살고, 아침 기도와 식사를 마친 뒤 일하러 나가는 일상이 있다.","source":"S-f7301c18bfae"},{"label":"능력","value":"카카투의 은혜로 신성력을 사용한다. 동료의 몸 상태를 살피고 치유를 돕지만, 오래된 손상처럼 자신의 능력으로 해결하기 어려운 경우도 구분한다.","source":"S-a93aee63b76c"},{"label":"가족","value":"인간인 미샤의 반려자. 서로를 숨기지 않고 당당히 사랑하며 여행하고 싶다는 바람이 가문을 떠나는 결정으로 이어진다.","source":"S-f80c598e4db0"}],"evaluation":[{"title":"자기 삶을 선택하는 용기","text":"가문의 보장된 생활을 사슬에 묶인 코끼리에 빗대며, 미샤와 자유롭게 사랑하고 여행하는 삶을 원한다고 말한다. 생활의 어려움에 관한 미샤의 질문을 듣고도 함께 떠날 이유를 구체화한다. 타인의 말에서 용기를 얻은 뒤 자신의 선택으로 옮기는 힘이 있는 인물이다.","source":"S-f80c598e4db0"},{"title":"웃으며 가까워지는 사람","text":"맡겨진 종족 문화 교류회를 귀찮아하면서도 사람들을 부르고 소개 순서를 정하며 대화를 이끈다. 격식을 가볍게 풀어내는 농담과 거리낌 없는 말투가 모임의 분위기를 만든다. 처음부터 모두를 이해하는 인물은 아니며, 서로의 차이를 생활 속에서 부딪치고 배워간다.","source":"S-7c736b1d84bd"},{"title":"존엄을 지키는 현실적인 대응","text":"차별적인 상인 앞에서는 물러나지 않고 제대로 된 사과를 요구한다. 길드 소속과 망명 절차를 거친 신분, 장사에 미칠 영향을 짚으며 상대를 설득하고 압박한다. 화가 나는 상황에서도 자신의 처지와 사용할 수 있는 수단을 생각하는 면모가 드러난다.","source":"S-4fad1d04608a"},{"title":"가족을 지키기 위해 감수하는 타협","text":"길란과의 만남에서는 라운데라 교단에 동족과 서부인의 동향을 보고하고, 이를 골기아에서 가족·동료·신앙을 지키기 위한 적응으로 설명한다. 필요한 사람과 가까워져야 한다는 계산도 숨기지 않는다. 이 선택에는 현실 감각과 씁쓸한 타협이 함께 있으며, 그의 친화력에 생존의 사정이 얽혀 있음을 보여준다.","source":"S-9fe18be02a0b"},{"title":"살아 있는 동료를 위해 싸우고 믿음을 배우다","text":"티아멧의 유해를 찾는 여정 뒤, 죽은 이를 위해 목숨을 거는 동료들을 온전히 이해하지 못했다고 말한다. 자신은 위험에 처한 살아 있는 동료들을 위해 싸웠다는 것이다. 션의 이야기를 들으며 가까운 사람들을 믿어보겠다고 답하고, 자신의 생각도 바꿀 필요가 있음을 인정한다. 애정과 두려움을 품은 채 관계의 폭을 넓혀가는 모습이 인상적이다.","source":"S-7ac67eae8ee4"}],"traits":{"social":{"score":5,"text":"문화 교류회에서 사람들을 부르고 자기소개와 문답을 이끈다. 비를 맞고 찾아온 어거스트를 맞아 불과 담요를 챙기고, 모카에게 서로 좋아하는 음식을 먹어보자고 제안하는 등 새 접점을 만드는 행동이 반복된다.","source":"S-7c736b1d84bd","supportingSources":["S-02e2a5196fb5","S-b93ec61f9dd6"]},"emotion":{"score":4,"text":"미샤가 없는 악몽의 불안을 동료들에게 털어놓고, 미샤의 비밀 의뢰를 오해했을 때는 션에게 관계를 상담한다. 애정과 불안이 판단에 영향을 주지만, 대화를 통해 돌아보고 진정하려는 모습도 있다.","source":"S-861086b4090d","supportingSources":["S-28e0b7447b47"]},"altruism":{"score":4,"text":"비에 젖은 낯선 방문자를 챙기고 동료의 몸 상태를 살핀다. 티아멧의 여정에서는 살아 있는 동료들이 위험해서 싸웠다고 설명한다. 주변 사람을 실제로 돕되, 무조건적인 자기희생을 당연하게 여기지는 않는 성향으로 읽힌다.","source":"S-7ac67eae8ee4","supportingSources":["S-02e2a5196fb5","S-a93aee63b76c"]},"initiative":{"score":4,"text":"가문을 떠나 미샤와 살 길을 직접 제안하고 실행한다. 모임의 진행을 맡아 사람들을 모으고, 차별적인 상인에게는 사과를 받아낼 때까지 행동한다. 매번 앞장서는 지휘관은 아니지만 중요한 선택과 일상의 문제를 스스로 움직여 풀어간다.","source":"S-f80c598e4db0","supportingSources":["S-7c736b1d84bd","S-4fad1d04608a"]},"caution":{"score":3,"text":"떠내려온 물고기를 확인 없이 먹어 배탈이 나는 등 일상에서는 즉흥적인 면이 있다. 반면 상인의 차별에는 신분과 손익을 이용해 대응하고, 가족과 신앙에 관한 일에는 골기아 사회의 위험과 이해관계를 계산한다. 상황에 따라 신중함의 정도가 달라지는 인물로 평가했다.","source":"S-9fe18be02a0b","supportingSources":["S-4fad1d04608a","S-fb96aac6cfe4","S-f7301c18bfae"]},"bonds":{"score":5,"text":"미샤의 외로움과 짐을 함께 감당하며 곁에 있겠다고 약속한다. 티아멧의 여정 뒤에는 션과 동료들을 믿는 법을 고민한다. 가까운 이들과 함께 살아갈 관계가 선택의 큰 기준이 된다.","source":"S-7ab1c252d917","supportingSources":["S-7ac67eae8ee4"]}},"relations":[{"name":"라이아흐 미샤","text":"가문을 떠나 함께 정착한 반려자. 사랑과 자유를 함께 선택했으며, 불안과 오해를 겪으면서도 서로의 삶을 나누려 한다.","source":"S-7ab1c252d917","characterId":"P-41ba4c5736e6"},{"name":"션","text":"미샤에 관한 불안과 동료에 대한 믿음을 상담한 친구. 티아멧의 여정 뒤 신뢰를 어떻게 배울지 이야기를 나눈다.","source":"S-7ac67eae8ee4","characterId":"P-3bbc4a823df9"},{"name":"사이먼 피터 포레스트","text":"서로의 몸 상태를 살피며 신앙과 치유의 한계를 이야기한 동료.","source":"S-a93aee63b76c","characterId":"P-3ea4affc20fd"},{"name":"모카","text":"서로 좋아하는 음식을 먹어보자고 제안하고 데미간 시장의 음식 문화를 함께 경험한 동료.","source":"S-b93ec61f9dd6","characterId":"P-f400f584340f"},{"name":"폴라리스","text":"바꿀 수 없는 과거와 길드의 어린 인물들을 어떻게 대할지 걱정을 나눈 동료.","source":"S-8e1231167356","characterId":"P-5d0c306440d0"}],"scenes":[{"source":"S-f80c598e4db0","text":"가문의 사슬을 벗어나 미샤와 자유롭게 살기로 결정한 대화."},{"source":"S-7ab1c252d917","text":"이해하지 못했던 외로움까지 함께 짊어지겠다는 약속."},{"source":"S-f7301c18bfae","text":"기도와 아침 식사, 살롱의 마사지 일을 이어가는 평소의 생활."},{"source":"S-4fad1d04608a","text":"차별을 당한 시장에서 자신의 존엄과 사과를 요구하는 방식."},{"source":"S-7ac67eae8ee4","text":"위험한 여정 뒤 션과 나눈 삶의 가치와 동료에 대한 믿음."},{"source":"S-9fe18be02a0b","text":"골기아에서 가족과 신앙을 지키기 위해 감수하는 타협과 계산."}],"updatedAt":"2026-09-29","asOf":"2026-09-24","sources":["S-4fad1d04608a","S-f80c598e4db0","S-f7301c18bfae","S-a93aee63b76c","S-7c736b1d84bd","S-9fe18be02a0b","S-7ac67eae8ee4","S-02e2a5196fb5","S-b93ec61f9dd6","S-861086b4090d","S-28e0b7447b47","S-fb96aac6cfe4","S-7ab1c252d917","S-8e1231167356"]},"P-b522cca806d0":{"name":"에스텔 벨라시타","tagline":"누군가를 구하는 길 위에서 자신도 소중히 여기는 법을 배우는 사람.","tags":["헌신적","자기성찰적인","마음 표현이 섬세한"],"profileNote":"벨라시타와 베라시타는 같은 인물이다. 성기사를 꿈꾸지만, 아서와의 대화에서는 아직 사제도 기사도 아니며 신성력이 없다고 스스로 설명한다. 출생의 비밀은 인물이 아는 내용과 추정의 범위를 구분했다.","facts":[{"label":"성장 배경","value":"어린 시절 성기사에게 구조되어 로운델 변방의 수녀원에서 자랐다. 자신을 구해준 사람과 같은 성기사가 되고 싶어 약 15살에 수녀원을 떠났다고 말한다.","source":"S-4787c94fc568"},{"label":"출생에 관한 고백","value":"생모를 포함한 희생자들이 바쳐진 흑주술 의식 속에서 태어났다고 토르번에게 털어놓는다. 정확히 어떤 의식이었는지, 자신에게 무엇을 남겼는지는 다 알지 못한다.","source":"S-9d683124e3f2"},{"label":"계속되는 조사","value":"잠결에 그린 문양을 도리안에게 보내 그 효과와 연결된 존재를 알아봐 달라고 부탁한다. 도리안도 즉시 답을 확정하지 못하며, 출생과 문양의 관계는 조사 중인 문제로 남는다.","source":"S-cc7e377a27cb"},{"label":"전투와 훈련","value":"한쪽 다리의 무릎 아래를 잃은 뒤 의족을 사용한다. 근력 운동과 검술 연습을 이어가고, 브랜의 도움으로 전투에 쓸 판금 의족을 마련한다.","source":"S-a2267866e320"},{"label":"길드에서 하는 일","value":"토르번의 집무실에서 서류를 돕고 임무와 교섭을 함께 고민한다. 사자회와의 충돌을 막기 위해 소규모 사절단을 먼저 보내자는 의견을 낸다.","source":"S-1e96be16c475"},{"label":"일상의 실천","value":"교회에서 빈민 급식을 준비하는 일을 돕는다. 사람을 구하고 싶다는 바람은 큰 임무 밖의 봉사와 노동으로도 이어진다.","source":"S-4185f70d4c10"}],"evaluation":[{"title":"선의에 얽힌 존재의 질문","text":"타인을 구하는 것 외에는 자신이 존재해도 된다는 확신을 얻지 못한다면 어떻게 해야 하느냐고 루체에게 묻는다. 남을 돕는 열망에는 자신의 출생을 죄처럼 짊어진 마음도 얽혀 있다. 루체 앞에서 자신을 소중히 여기겠다고 말하는 장면은, 그 부담을 스스로 알아보고 다른 길을 연습하는 시작점이다.","source":"S-65466fac2104"},{"title":"미움받을까 두려워도 내는 의견","text":"스텔라의 계획에 반대하면서 상관과 동료에게 미움받을까 두려웠다고 고백한다. 그럼에도 사람들이 다치거나 죽는 것이 더 싫어서 사절단을 제안했다. 순응적인 말투 안에도 자신의 판단을 지키는 힘이 있고, 상대가 위협을 느끼지 않게 접근할 방법까지 생각한다.","source":"S-9d683124e3f2"},{"title":"몸의 변화에 맞춰 계속 배우다","text":"의족을 쓴 몸으로 어떻게 버티고 움직일지 직접 훈련하고, 새로운 장비를 마련한다. 브랜에게 제작을 맡기고 도움에 감사하는 모습도 함께 나온다. 상실 뒤의 에스텔은 혼자 견디기만 하는 인물이 아니라, 동료의 기술과 자신의 노력을 연결해 다음 행동을 준비하는 인물이다.","source":"S-a2267866e320"},{"title":"편지와 고백으로 넓어지는 신뢰","text":"부상을 걱정시킬까 만남을 피하면서도 토르번과 필담을 이어가고, 훗날에는 출생의 비밀까지 털어놓는다. 두 사람은 자신 대신 희생된 이들의 이야기를 나눈다. 작은 장난과 부끄러움이 쌓인 관계가, 감추고 싶었던 부분까지 보여줄 수 있는 신뢰로 깊어진다.","source":"S-9d683124e3f2"},{"title":"혼자 갚는 삶에서 도움을 청하는 삶으로","text":"도리안에게 문양의 조사를 부탁하기까지는 동료를 사적인 일에 끌어들여도 되는지 망설인다. 결국 먼저 손을 내밀고, 출생의 기억을 들려주기로 한다. 남에게 기대도 된다는 말을 뒤늦게 받아들이는 변화는 에스텔의 성장에서 중요한 부분이다.","source":"S-cc7e377a27cb"}],"traits":{"social":{"score":3,"text":"예의를 갖춰 대화하고 도움을 요청할 수 있지만, 상처나 비밀을 보이는 일에는 오래 망설인다. 토르번과는 편지로 거리를 좁히고 도리안에게는 조심스럽게 상담을 청한다. 폭넓은 접근보다 신뢰를 쌓은 뒤 깊어지는 교류에 가깝다.","source":"S-006a9f46a0cf","supportingSources":["S-cc7e377a27cb","S-4787c94fc568"]},"emotion":{"score":4,"text":"걱정시키고 싶지 않은 마음과 미움받을까 하는 두려움이 행동을 망설이게 한다. 신뢰받는 순간에는 부끄러움과 눈물, 고마움도 선명하게 표현한다. 감정이 크면서도 상대를 배려해 표현을 고르는 편이다.","source":"S-9d683124e3f2","supportingSources":["S-006a9f46a0cf","S-65466fac2104"]},"altruism":{"score":5,"text":"타인을 구하는 일을 자신의 존재 이유와 연결할 만큼 중요하게 생각한다. 교회의 봉사를 돕고, 동료들이 다칠 위험을 줄이기 위해 상관에게 반대 의견도 낸다. 그 헌신이 자기 소모로 이어질 수 있다는 점까지 포함한 평가다.","source":"S-65466fac2104","supportingSources":["S-4185f70d4c10","S-1e96be16c475"]},"initiative":{"score":4,"text":"사절단을 먼저 제안하고 교섭 방식을 고민한다. 의족과 훈련을 준비하며 출생의 문양도 스스로 조사 의뢰한다. 머뭇거림이 있어도 필요한 일을 판단하면 직접 움직이는 장면이 반복된다.","source":"S-1e96be16c475","supportingSources":["S-a2267866e320","S-cc7e377a27cb"]},"caution":{"score":3,"text":"교섭에서는 상대를 자극할 위험과 정보 수집, 충돌을 피할 방법을 따진다. 반면 자기 부상은 숨기고 자신을 희생의 예외로 두기 쉽다. 다른 사람의 안전을 살피는 능력과 자기 보호의 어려움을 함께 반영했다.","source":"S-9d683124e3f2","supportingSources":["S-006a9f46a0cf","S-65466fac2104"]},"bonds":{"score":5,"text":"토르번의 편지를 소중히 간직하고 깊은 비밀을 나누며, 루체와 한 자기 보호의 약속을 받아들인다. 도리안이 해주었던 말을 기억하고 다시 찾아가는 모습에서도 관계의 말을 오래 품는 성향이 드러난다.","source":"S-006a9f46a0cf","supportingSources":["S-9d683124e3f2","S-65466fac2104","S-cc7e377a27cb"]}},"relations":[{"name":"토르번 팔켄하인","text":"편지와 안부를 주고받고 교섭의 역할을 함께 나누는 상대. 서로의 출생과 희생의 기억을 고백하며 신뢰가 깊어진다.","source":"S-9d683124e3f2","characterId":"P-7ba611cf90be"},{"name":"루체 루멘","text":"구하려는 사람들 속에 에스텔 자신도 들어가야 한다고 끈질기게 말해준 동료. 자신을 소중히 여기겠다는 약속을 나눈다.","source":"S-65466fac2104","characterId":"P-d8e7afee7c51"},{"name":"브랜","text":"판금 의족을 제작하고 필요하면 다시 손봐주겠다고 한 동료. 에스텔이 계속 움직이고 싸울 수 있도록 기술로 돕는다.","source":"S-a2267866e320","characterId":"P-55e987e3c831"},{"name":"도리안 바이덴스","text":"기대도 된다는 말을 기억하게 한 동료이자 문양의 조사를 부탁한 상대. 숨기던 출생의 이야기를 직접 들려준다.","source":"S-cc7e377a27cb","characterId":"P-dd70a1273f02"},{"name":"아서 나이츠베인","text":"기사란 무엇인지, 재능과 지위 없이도 무엇을 추구할 수 있는지 이야기한 동료. 서로의 이상을 다시 바라보게 한다.","source":"S-4787c94fc568","characterId":"P-9d7bf25dbba3"}],"scenes":[{"source":"S-4185f70d4c10","text":"구하고 싶은 마음이 빈민 급식 준비라는 일상의 노동으로 이어지는 장면."},{"source":"S-006a9f46a0cf","text":"부상을 숨긴 마음과 걱정, 장난이 쌓이는 집무실의 편지."},{"source":"S-9d683124e3f2","text":"미움받을 두려움을 넘어 낸 의견과 토르번에게 들려주는 출생의 비밀."},{"source":"S-cc7e377a27cb","text":"도리안에게 문양의 조사를 부탁하며 먼저 도움의 손을 뻗는 대화."},{"source":"S-a2267866e320","text":"꾸준한 훈련과 브랜의 제작으로 완성되는 새 판금 의족."},{"source":"S-65466fac2104","text":"루체 앞에서 자신도 소중히 여기겠다고 말하는 순간."}],"updatedAt":"2026-09-29","asOf":"2026-09-26","sources":["S-4787c94fc568","S-9d683124e3f2","S-cc7e377a27cb","S-a2267866e320","S-1e96be16c475","S-4185f70d4c10","S-65466fac2104","S-006a9f46a0cf"]},"P-d8e7afee7c51":{"name":"루체 루멘","tagline":"소중한 사람을 지키기 위해 어른에게도 필요한 질문을 던지는 사람.","tags":["직설적인","동료를 아끼는","행동하는"],"profileNote":"루멘 수도원에서 나온 어린 모험가의 활동을 정리했다. 어른에게 보호받는 일상과 실제 임무에서 판단하고 행동하는 모습을 함께 읽었다. 션과 숀은 서로 다른 인물이며, 여기서 아빠라고 부르는 상대는 션이다.","facts":[{"label":"출신","value":"루멘 수도원에서 지냈으며, 어머니가 몸담았던 인연을 따라 어설픈 용맹을 찾아온다. 수도원으로 돌아가기 싫다는 뜻을 분명히 밝힌다.","source":"S-7bab4166ab21"},{"label":"어머니","value":"스텔라가 티아리엘 산크타 룩스라는 이름을 알아보고, 멜라니온도 어머니와의 인연을 이야기한다. 길드에서의 첫 만남부터 어머니가 남긴 관계가 루체를 둘러싼다.","source":"S-7bab4166ab21"},{"label":"신앙과 능력","value":"라운데라에게 기도하고 신성력을 사용한다. 에켈수르 사건에서 상자의 기운을 살피고 기도로 갈 길을 묻는 등 신앙을 실제 사건 해결에 연결한다.","source":"S-3d36d422dff8"},{"label":"임무에서의 역할","value":"알아즈라 구출에 참여해 예비 수녀복을 활용하고, 지도에서 우물과 저수지의 연결을 찾아 탈출을 제안한다. 리엔 등 동료들의 능력과 함께 이동 방법을 마련한다.","source":"S-9a32dd671a68"},{"label":"가까운 가족 관계","value":"션과 서로 아빠와 딸로 대하는 관계다. 책을 읽어주거나 스스로 읽으면 용돈을 주겠다고 약속하는 식의 일상적인 돌봄이 기록되어 있다.","source":"S-407e4ad91cf4"},{"label":"중요하게 여기는 문제","value":"나이가 어리다는 이유로 동료의 선택을 배제하는 일에 반발한다. 아서를 남겨둔 판단에 관해 토르번에게 직접 묻고 신뢰의 기준을 따진다.","source":"S-92e4ccdfb559"}],"evaluation":[{"title":"자신의 자리부터 직접 요구하다","text":"길드에 처음 들어올 때부터 돌아가기 싫은 곳과 머물고 싶은 곳을 분명히 말한다. 어머니의 인연으로 어른들의 관심을 받지만, 그 안에서 자신의 의사도 강하게 드러낸다. 보호받는 위치에서도 스스로 결정하려는 태도가 이후의 활동으로 이어진다.","source":"S-7bab4166ab21"},{"title":"보호 속에 가려진 선택권을 묻다","text":"토르번에게 아서의 일을 따져 묻는 것은 단순한 반항으로만 읽기 어렵다. 루체가 중요하게 보는 것은 위험을 함께 감수할 동료로 인정받고, 자신이 모르는 곳에서 결정이 끝나지 않는 관계다. 상대에게도 사정이 있다는 설명을 듣지만 의견 차이가 완전히 사라지는 것은 아니다.","source":"S-92e4ccdfb559"},{"title":"신앙을 행동과 연결하는 문제 해결","text":"궁전 구출에서 기도로 얻은 실마리를 지도와 연결하고 우물의 상태를 손본다. 말로 해법을 내는 데서 그치지 않고 밧줄과 이동 경로를 준비하는 모습이 보인다. 탈출은 동료들의 협력으로 이루어지며, 루체의 강점은 그 협력이 향할 구체적인 방향을 찾는 데 있다.","source":"S-9a32dd671a68"},{"title":"친구의 자기희생에 동의하지 않는 다정함","text":"에스텔이 타인을 구해야 자신의 존재를 긍정할 수 있다고 말하자, 루체는 이미 존재하는 사람의 소중함을 되묻는다. 부드럽게 달래기보다 상대가 직접 자신을 소중히 여기겠다고 말할 때까지 대화를 이어간다. 직설적인 말투가 가까운 사람을 지키는 애정의 방식이 된다.","source":"S-65466fac2104"},{"title":"배움과 장난이 함께 있는 일상","text":"션에게 책을 읽어달라고 하고 용돈 약속을 받는 모습에는 아직 돌봄과 배움이 필요한 나이가 드러난다. 어른에게 질문하고 임무를 해결하는 능력과 이런 일상은 함께 존재한다. 모든 장면에서 작은 어른일 필요가 없다는 점이 루체를 더 입체적으로 만든다.","source":"S-407e4ad91cf4"}],"traits":{"social":{"score":4,"text":"첫 방문부터 자신의 의사를 직접 말하고, 필요한 논쟁이 있으면 토르번에게 먼저 찾아간다. 에스텔과는 진로와 출신을 묻는 대화를 깊게 이어간다. 말투가 거침없을 때도 있지만 사람과의 접점을 주저 없이 만든다.","source":"S-7bab4166ab21","supportingSources":["S-92e4ccdfb559","S-65466fac2104"]},"emotion":{"score":4,"text":"동료를 배제했다고 느끼면 분명하게 반발하고, 수도원으로 돌아가기 싫은 마음도 숨기지 않는다. 에스텔을 아끼는 마음 역시 반복되는 질문과 요구로 표현한다. 좋고 싫음과 걱정이 행동에 잘 드러나는 편이다.","source":"S-92e4ccdfb559","supportingSources":["S-7bab4166ab21","S-65466fac2104"]},"altruism":{"score":4,"text":"에스텔이 자신을 소모하지 않도록 긴 대화를 나누고, 위험한 구출에서는 일행이 빠져나갈 방법을 찾는다. 개인의 신앙과 행동력이 주변 사람을 살리고 함께 돌아오는 방향으로 사용된다.","source":"S-65466fac2104","supportingSources":["S-9a32dd671a68","S-3d36d422dff8"]},"initiative":{"score":5,"text":"동료의 처우에 관해 직접 질문하고, 에켈수르에서는 상자를 옮겨 문제를 해결하는 행동에 나선다. 궁전에서도 단서를 연결해 탈출로를 제안하고 준비한다. 필요하다고 판단하면 말과 행동 양쪽에서 먼저 움직인다.","source":"S-9a32dd671a68","supportingSources":["S-3d36d422dff8","S-92e4ccdfb559"]},"caution":{"score":3,"text":"궁전에서는 복장과 지도, 우물과 밧줄을 활용해 이동을 준비한다. 한편 비버 댐 소동에서는 라르손의 양말을 이용한 과감한 방법이 뒤탈을 남긴다. 준비할 줄 아는 능력과 즉흥적인 대담함을 함께 반영한 점수다.","source":"S-9a32dd671a68","supportingSources":["S-ab7cb0c49ff3"]},"bonds":{"score":5,"text":"함께하는 사람을 동료로 믿고 존중해야 한다는 기준이 강하다. 션과의 가족 같은 일상, 에스텔의 자기 보호를 요구하는 대화에서도 가까운 관계를 계속 돌보려는 태도가 드러난다.","source":"S-92e4ccdfb559","supportingSources":["S-407e4ad91cf4","S-65466fac2104"]}},"relations":[{"name":"션","text":"아빠와 딸로 대하며 책 읽기와 용돈, 돌봄을 나누는 가족 관계. 임무 밖에서 루체가 기대고 배우는 일상을 보여준다.","source":"S-407e4ad91cf4","characterId":"P-3bbc4a823df9"},{"name":"에스텔 벨라시타","text":"각자 수녀원에서 지냈다는 접점에서 진로와 자기 가치를 이야기한 동료. 에스텔 자신도 지켜야 한다고 요구한다.","source":"S-65466fac2104","characterId":"P-b522cca806d0"},{"name":"토르번 팔켄하인","text":"동료의 안전과 선택권을 두고 직접 논쟁하는 대장. 보호하려는 판단에도 신뢰에 관한 질문을 던진다.","source":"S-92e4ccdfb559","characterId":"P-7ba611cf90be"},{"name":"리엔 에이라스","text":"알아즈라에서 구출과 탈출을 함께한 동료. 루체가 찾은 경로와 리엔의 정령술이 협력하는 모습을 볼 수 있다.","source":"S-9a32dd671a68","characterId":"P-a161473e74e0"},{"name":"모나 델핀","text":"축제를 함께 즐기다가 검은 비의 사건까지 맞닥뜨린 동료. 모나는 루체를 돌보면서도 사건을 해결하는 행동을 함께한다.","source":"S-3d36d422dff8","characterId":"P-48cca58d02b2"}],"scenes":[{"source":"S-7bab4166ab21","text":"어머니의 이름과 루멘 수도원의 사정이 밝혀지는 첫 길드 방문."},{"source":"S-3d36d422dff8","text":"즐거운 축제에서 검은 비의 위기로, 기도와 상자를 둘러싼 선택."},{"source":"S-92e4ccdfb559","text":"동료를 보호한다는 말과 선택권을 믿는다는 말 사이의 논쟁."},{"source":"S-407e4ad91cf4","text":"션이 읽어주는 책과 스스로 읽은 뒤 받을 용돈의 약속."},{"source":"S-9a32dd671a68","text":"위장과 지도, 우물의 연결로 찾아내는 궁전의 탈출 경로."},{"source":"S-65466fac2104","text":"에스텔에게 자신의 소중함을 직접 말하게 하는 대화."}],"updatedAt":"2026-09-29","asOf":"2026-09-26","sources":["S-7bab4166ab21","S-3d36d422dff8","S-9a32dd671a68","S-407e4ad91cf4","S-92e4ccdfb559","S-65466fac2104","S-ab7cb0c49ff3"]},"P-48cca58d02b2":{"name":"모나 델핀","tagline":"두려워하는 동료에게 살아 돌아올 이유를 건네는 사람.","tags":["다정한","생명을 존중하는","귀환을 바라는"],"profileNote":"찹츄·챱츄로 남은 프로필도 모나의 기록에 포함한다. 자연과 순환에 관한 말은 모나의 관점으로 정리했으며, 순환을 겪는 꿈을 실제 사망이나 환생 이력으로 단정하지 않았다.","facts":[{"label":"성장 배경","value":"단델리온 유랑단에서 지냈다. 함께 자란 데미간들을 가족으로 여기며, 유랑단 시절부터 잡일과 어린 동생들을 돌보는 일에 익숙했다고 말한다.","source":"S-44fd8459dc7f"},{"label":"가족의 범위","value":"혈연과 종족에 한정하지 않고 유랑단과 길드 사람들을 가족으로 부른다. 새로 온 루체에게도 가족이 되었다고 환영한다.","source":"S-7bab4166ab21"},{"label":"능력","value":"자연력을 다루고 동물로 변신하는 드루이드다. 토팔에서는 식물 줄기를 자라게 하고 시들게 하는 능력을 상황에 맞게 활용한다.","source":"S-270dd493703c"},{"label":"자연관","value":"릴리 할머니에게 배운 순환의 관점을 이야기한다. 농사도 자연의 순리를 따르는 일이며 죽음도 새로운 생명으로 이어진다고 보고, 서로 다른 자연관에 관심을 보인다.","source":"S-70d9b92f2bd2"},{"label":"중요한 사건","value":"도착하지 않는 유랑단 가족을 기다리다 근심하는 모습이 단델리온 구출 사건의 출발점이 된다. 동료들이 가족의 행방을 찾아 나서며 길드와 유랑단의 인연이 이어진다.","source":"S-ff3ac8a00b17"},{"label":"돌봄을 받는 시간","value":"토팔에서 팔을 다친 뒤 라이티티아에게 포션과 돌봄을 받는다. 자신을 도와준 일에 감사하면서 라이티티아도 쉬어야 한다고 당부한다.","source":"S-e37297ab4b6c"}],"evaluation":[{"title":"가족으로 맞아들이는 환대","text":"새 사람에게 인사하고 자연스럽게 가족이라는 말을 건넨다. 그 말에는 다양한 데미간과 함께 자란 유랑단의 경험이 깔려 있다. 종족이나 외모가 달라도 한 울타리에서 돌보고 지낼 수 있다는 생각이 길드의 일상에서도 반복된다.","source":"S-7bab4166ab21"},{"title":"두려움을 없애는 대신 다음 걸음을 찾다","text":"엘레나가 죽음과 배신을 두려워하자 그 감정을 당연한 것으로 받아들인다. 물건을 대신 맡아주는 대신 무사히 돌아가 직접 전할 이유로 간직하라고 권한다. 모나의 위로는 감정을 부정하지 않으면서 살아갈 다음 행동을 찾게 하는 방식이다.","source":"S-5660e15d73e6"},{"title":"순환의 관점을 애도에 쓰다","text":"토팔에서 마리나의 무덤 곁에 꽃을 피우고 다음 순환에서 다시 만나기를 빈다. 다른 동료의 상실 앞에서도 작은 꽃으로 애도를 건넨다. 생명과 죽음의 순환을 믿는 태도가 슬픔을 가볍게 넘기는 이유가 되지 않고, 떠난 존재를 기억하는 행동으로 이어진다.","source":"S-270dd493703c"},{"title":"다정함 뒤에 있는 실무와 대응력","text":"에켈수르 축제에서 루체를 챙기고, 지크를 둘러싼 소동에는 정중히 말을 건네 상황을 풀려 한다. 검은 비가 내리자 원인을 찾고 동료들과 함께 움직이려 한다. 돌봄의 말뿐 아니라 주변을 살피고 문제에 개입하는 행동도 모나의 중요한 면이다.","source":"S-3d36d422dff8"},{"title":"돌보는 사람도 기대어 쉴 수 있다","text":"다친 팔이 아파도 처음에는 괜찮다고 말하지만, 라이티티아가 건네는 도움을 받고 고마움을 표현한다. 동시에 상대의 무리도 알아보고 휴식을 권한다. 늘 여유롭게 남을 챙길 수 있는 존재라기보다, 서로의 약한 순간을 돌보며 관계를 이어가는 사람으로 읽힌다.","source":"S-e37297ab4b6c"}],"traits":{"social":{"score":4,"text":"신입 때 모닥불에 어울리고 새로 온 루체에게 가족이라는 말을 건네는 등 환영과 인사에 적극적이다. 정령과 길드 사람들에게 먼저 말을 걸며 새로운 만남을 일상의 공동체 안으로 들인다.","source":"S-cd92a7ca2914","supportingSources":["S-7bab4166ab21","S-70d9b92f2bd2"]},"emotion":{"score":4,"text":"가족이 오지 않자 근심하고, 동료의 귀환에는 고마움을 표현한다. 엘레나의 두려움과 토팔에서의 상실에도 함께 반응한다. 밝고 다정한 말투 안에 걱정과 슬픔을 받아들이는 감정의 폭이 있다.","source":"S-ff3ac8a00b17","supportingSources":["S-44fd8459dc7f","S-5660e15d73e6","S-270dd493703c"]},"altruism":{"score":4,"text":"어린 동료를 챙기고 집안일을 함께하며, 상실을 겪은 사람 곁에 머문다. 다쳤을 때에도 자신을 돌봐준 상대의 휴식을 걱정한다. 스스로의 휴식과 도움도 필요한 사람이라는 점을 함께 반영했다.","source":"S-e37297ab4b6c","supportingSources":["S-44fd8459dc7f","S-3d36d422dff8","S-270dd493703c"]},"initiative":{"score":4,"text":"동료가 충돌한 자리에서 대화를 시도하고 검은 비의 원인을 찾자고 제안한다. 토팔에서는 자연력을 상황에 맞게 응용하고, 엘레나에게는 맡기려는 물건의 의미를 바꿔 제시한다. 조용히 따르기만 하는 돌봄은 아니다.","source":"S-3d36d422dff8","supportingSources":["S-270dd493703c","S-5660e15d73e6"]},"caution":{"score":4,"text":"엘레나에게 복수를 위해 몸을 내던지기보다 우선 살아 돌아갈 이유를 붙잡게 한다. 축제의 위험 앞에서는 동료들과 함께 조사하려 하고, 부상 뒤에는 서로 쉬어야 한다고 당부한다. 다만 자기 통증을 처음에 괜찮다고 넘기는 모습도 있다.","source":"S-5660e15d73e6","supportingSources":["S-3d36d422dff8","S-e37297ab4b6c"]},"bonds":{"score":5,"text":"유랑단과 길드 사람들을 가족으로 여기며, 동료가 돌아갈 사람과 장소를 소중하게 생각한다. 돌아온 마리아를 환영하고 떠난 이에게도 꽃과 기억을 남긴다. 함께 지내온 관계를 이어가려는 태도가 중심에 있다.","source":"S-7bab4166ab21","supportingSources":["S-ff3ac8a00b17","S-5660e15d73e6","S-44fd8459dc7f"]}},"relations":[{"name":"엘레나 레지아노","text":"죽음과 배신의 두려움을 털어놓은 동료. 모나는 물건을 맡아주는 대신 함께 살아 돌아갈 이유를 건네준다.","source":"S-5660e15d73e6","characterId":"P-89d5e8c6329e"},{"name":"마리아 아나이스 에스더","text":"설거지를 함께하며 각자의 변화를 나누는 동료. 돌아와 줘서 고맙다고 환영하고, 외모와 매력을 바라보는 자신의 경험을 이야기한다.","source":"S-44fd8459dc7f","characterId":"P-c9505ea97ebc"},{"name":"루체 루멘","text":"새 가족으로 맞아들인 어린 동료. 축제의 일상에서는 돌보고, 위기에서는 함께 상자를 옮기며 해결에 나선다.","source":"S-3d36d422dff8","characterId":"P-d8e7afee7c51"},{"name":"라이티티아","text":"부상 뒤 포션과 자장가로 모나를 돌본 동료. 모나도 도움을 받아들이고 상대의 휴식을 챙기며 돌봄을 주고받는다.","source":"S-e37297ab4b6c","characterId":"P-fae6af716ea2"}],"scenes":[{"source":"S-ff3ac8a00b17","text":"늦어지는 가족의 소식에서 시작되는 단델리온 유랑단 구출."},{"source":"S-70d9b92f2bd2","text":"언데드로 돌아온 동료와 새로운 사람들을 맞으며 나누는 자연과 순환 이야기."},{"source":"S-6863afb166b8","text":"여러 생명의 순환을 꿈꾸고 양의 모습으로 잠든 밤."},{"source":"S-5660e15d73e6","text":"엘레나가 맡기려던 물건을 살아 돌아올 이유로 바꾸는 대화."},{"source":"S-e37297ab4b6c","text":"부상 뒤 모나가 도움을 받고, 도와준 사람의 휴식도 챙기는 시간."},{"source":"S-270dd493703c","text":"자연력을 활용한 싸움과, 상실 뒤 꽃을 피워 건네는 애도."}],"updatedAt":"2026-09-29","asOf":"2026-09-26","sources":["S-44fd8459dc7f","S-7bab4166ab21","S-270dd493703c","S-70d9b92f2bd2","S-ff3ac8a00b17","S-e37297ab4b6c","S-5660e15d73e6","S-3d36d422dff8","S-cd92a7ca2914","S-6863afb166b8"]},"P-7ba611cf90be":{"name":"토르번 팔켄하인","tagline":"동료에게 구원받은 기억으로, 다시 동료의 내일을 지키려는 대장.","tags":["책임감 있는","걱정이 많은","애정 표현이 서툰"],"profileNote":"길드에서 공격대장을 맡는다. 팔켄하인 가문의 사건과 애건의 결말, 카일라와의 약속을 포함해 현재의 책임감이 생긴 배경을 함께 정리했다.","facts":[{"label":"역할","value":"스텔라에게 공격대장을 맡았다고 말한다. 길드원들을 책임지는 부담과 낭만적인 모험을 하고 싶은 마음을 시안에게 털어놓는다.","source":"S-5c80169e53df"},{"label":"실무","value":"업무 분담 뒤 길드원 관리를 맡는다. 스텔라는 왕가와 귀족에 관한 일, 션은 모험가 연합 등 대외 업무를 담당한다.","source":"S-39cc952fac30"},{"label":"가문과 형제","value":"팔켄하인 가문의 저주에 얽혀 있으며, 쌍둥이 동생 애건이 자신을 완벽한 팔켄하인으로 만들기 위한 제물로 바쳐졌다는 사실을 알게 된다. 동료들에게 도움을 요청하고 가문에 맞선다.","source":"S-6fa6dc7c1a69"},{"label":"전투 능력","value":"검을 사용하며 번개를 다루는 모습이 기록되어 있다. 팔켄하인 저택에서는 자신의 생명과 연결된 적을 상대하면서 동료들과 탈출과 대응책을 찾는다.","source":"S-6fa6dc7c1a69"},{"label":"기억하는 사람들","value":"애건의 일기를 보관하고, 자신 대신 희생된 동생과 시종들을 기린다. 에스텔에게 그 희생과 길드 동료들의 도움을 받은 것이 열심히 살아가는 이유라고 말한다.","source":"S-9d683124e3f2"},{"label":"카일라와의 약속","value":"죽음을 원하는 카일라에게 함께 짊어지겠다고 말하고 직접 검을 든다. 빼앗긴 목숨보다 더 많은 목숨을 살려 비명 대신 웃음이 들리게 하겠다고 약조한다.","source":"S-321f38393db2"}],"evaluation":[{"title":"도움을 받아 살아남은 사람이 책임을 맡다","text":"팔켄하인의 저주를 끊으려는 여정은 토르번이 동료들에게 도움을 청하면서 시작된다. 사건 뒤에는 애건의 일기를 남기고, 훗날 자신이 살아온 데에는 타인의 희생과 기대가 있었다고 고백한다. 책임감은 직책만의 문제가 아니라 자신을 구해준 이들에게 어떻게 응답할지에 관한 문제이기도 하다.","source":"S-9d683124e3f2"},{"title":"검으로 끝내기보다 살아갈 이유를 건네다","text":"카일라가 죽음을 원할 때 토르번은 그 선택을 도울 수 없다고 말한다. 직접 싸운 끝에 앞으로 함께 더 많은 생명을 구하겠다는 약속을 건넨다. 상대의 고통을 즉시 해결했다고 단정할 수는 없지만, 고통을 함께 짊어질 관계와 미래를 제안한다는 점이 토르번다운 장면이다.","source":"S-321f38393db2"},{"title":"싸움 전에 선택지를 확보하는 대장","text":"사자회에 대한 강경 대응을 보고 곧바로 전쟁에 해당할 수 있음을 지적한다. 에스텔의 사절단 제안을 받아들여 교섭과 정보 확인을 우선하고 필요한 인원을 고른다. 소중한 사람을 구하려는 목적을 놓지 않으면서도, 모두가 감당할 위험을 줄일 방법을 찾는다.","source":"S-1e96be16c475"},{"title":"보호하려는 판단도 질문받아야 한다","text":"루체가 아서를 남겨둔 일을 문제 삼자 당시 상황을 설명하고 과보호를 줄이겠다고 답한다. 다만 동료를 지킨다는 자신의 판단과 상대가 느끼는 배제 사이의 간극이 완전히 해소되지는 않는다. 책임을 지는 선의가 곧 정답은 아니라는 어려움이 이 관계에 남아 있다.","source":"S-92e4ccdfb559"},{"title":"대장이라는 호칭 뒤의 친구","text":"사이먼의 죽음을 듣고 더 잘해주지 못한 일을 후회하며, 무슨 일이 생겨도 자신의 책임처럼 느껴진다고 털어놓는다. 그러면서 시안에게 친구처럼 지내자고 청한다. 늘 버티는 대장의 모습 아래에는 책임을 잠시 내려놓고 동료들과 편하게 어울리고 싶은 사람도 있다.","source":"S-5c80169e53df"}],"traits":{"social":{"score":3,"text":"대장이라는 호칭이 만드는 거리를 느끼면서도 시안에게 친구처럼 지내자고 말한다. 에스텔에게는 편지로 마음을 전하며 머뭇거린다. 누구에게나 쉽게 다가가기보다 가까운 관계에서 조금씩 개인적인 얼굴을 보이는 편이다.","source":"S-5c80169e53df","supportingSources":["S-006a9f46a0cf","S-eb6cf10d0729"]},"emotion":{"score":4,"text":"동료의 죽음과 자신 대신 희생된 사람들에 대한 마음을 오래 품는다. 에스텔의 부상을 걱정하고 감춰진 사연을 들으며 자신의 기억도 나눈다. 감정을 절제해 말하는 편이지만 책임과 선택을 움직이는 힘은 크다.","source":"S-5c80169e53df","supportingSources":["S-9d683124e3f2","S-006a9f46a0cf"]},"altruism":{"score":4,"text":"카일라의 고통을 함께 짊어지고 앞으로 생명을 구하겠다고 약속한다. 가문의 사건이 끝날 때에는 억지로 동원된 영지민도 있을 것이라 보고 투항을 권고한다. 책임을 적극적으로 감수하되 모두를 혼자 구할 수 있다는 인물은 아니다.","source":"S-321f38393db2","supportingSources":["S-6fa6dc7c1a69","S-5c80169e53df"]},"initiative":{"score":5,"text":"가문의 저주에 맞서기 위해 도움을 청하고 직접 움직인다. 사자회 문제에서는 교섭 방안을 정하고 인원을 선발하며, 카일라에게는 행동과 약속으로 답한다. 개인의 위기와 공동의 일 양쪽에서 방향을 잡는 역할을 맡는다.","source":"S-1e96be16c475","supportingSources":["S-6fa6dc7c1a69","S-321f38393db2"]},"caution":{"score":4,"text":"사자회의 지도부와 바키르의 상태를 확인하고 무력 충돌을 마지막으로 미루는 순서를 세운다. 동료의 위험을 크게 보는 태도는 때로 과보호가 되기도 한다. 위험을 감수할 때에도 가능한 정보와 대안을 먼저 확보하려는 경향이 있다.","source":"S-9d683124e3f2","supportingSources":["S-1e96be16c475","S-92e4ccdfb559"]},"bonds":{"score":5,"text":"애건의 일기와 자신을 도운 사람들의 기억을 간직하고, 에스텔에게는 상처도 함께 나누어 달라고 말한다. 길드 사람들을 가족으로 부르며 함께 살아갈 약속을 중요하게 여긴다. 관계의 기억이 현재의 책임과 행동으로 이어진다.","source":"S-6fa6dc7c1a69","supportingSources":["S-006a9f46a0cf","S-eb6cf10d0729","S-321f38393db2"]}},"relations":[{"name":"에스텔 벨라시타","text":"편지와 작은 안부를 나누고, 교섭의 역할과 숨겨온 과거까지 공유하는 상대. 하고 싶은 말을 더 해도 된다며 판단을 믿어준다.","source":"S-9d683124e3f2","characterId":"P-b522cca806d0"},{"name":"루체 루멘","text":"보호하는 방식과 동료의 선택권을 직접 질문하는 동료. 토르번이 자신의 판단을 설명하고 돌아보게 한다.","source":"S-92e4ccdfb559","characterId":"P-d8e7afee7c51"},{"name":"시안 던 브링어","text":"사이먼의 죽음과 대장의 책임을 이야기한 동료. 직책이 만드는 거리 너머에서 친구처럼 지내고 싶다는 마음을 건넨다.","source":"S-5c80169e53df","characterId":"P-77d4478f4f51"},{"name":"스텔라 스타라이트","text":"길드의 위기를 함께 처리하지만 대응 방식에는 의견 차이도 있는 운영 동료. 사자회 문제에서 강경 대응을 교섭으로 조정하려 한다.","source":"S-1e96be16c475","characterId":"P-e6655a038328"},{"name":"션","text":"팔켄하인 가문의 저주에 맞서는 여정에 함께한 동료. 토르번이 자신의 위기를 길드에 맡길 수 있음을 보여주는 관계다.","source":"S-6fa6dc7c1a69","characterId":"P-3bbc4a823df9"}],"scenes":[{"source":"S-321f38393db2","text":"카일라에게 더 많은 목숨을 살리며 함께 짊어지겠다고 약속하는 대결."},{"source":"S-6fa6dc7c1a69","text":"가문의 저주에 맞서는 동료들, 애건의 희생과 남겨진 일기."},{"source":"S-5c80169e53df","text":"사이먼을 애도하며 대장이라는 책임과 친구라는 관계를 이야기하는 밤."},{"source":"S-006a9f46a0cf","text":"에스텔에게 상처도 나누어 달라고 적는 집무실의 편지."},{"source":"S-9d683124e3f2","text":"교섭의 역할을 나누다가 서로의 아픈 과거를 고백하는 시간."},{"source":"S-92e4ccdfb559","text":"루체의 질문 앞에서 보호와 신뢰의 기준을 다시 설명하는 대화."}],"updatedAt":"2026-09-29","asOf":"2026-09-23","sources":["S-5c80169e53df","S-39cc952fac30","S-6fa6dc7c1a69","S-9d683124e3f2","S-321f38393db2","S-1e96be16c475","S-92e4ccdfb559","S-006a9f46a0cf","S-eb6cf10d0729"]},"P-e6655a038328":{"name":"스텔라 스타라이트","tagline":"길드의 내일을 챙기면서 자신의 마법도 다시 찾으려는 사람.","tags":["실무적인","학구적인","책임을 중시하는"],"profileNote":"부길드장으로서의 운영 업무와 별을 좇아 마법을 배운 개인의 이야기를 함께 정리했다. 평소의 신중한 실무와 가까운 사람의 소식에 흔들리는 순간을 모두 성향 평가에 반영했다.","facts":[{"label":"길드에서의 역할","value":"어설픈 용맹의 부길드장. 12년 동안 운영을 맡아왔다고 회상하며, 토르번·션과 일을 나눈 뒤에는 주로 귀족과 왕가에 관한 업무를 처리한다.","source":"S-39cc952fac30"},{"label":"마법을 시작한 계기","value":"어릴 때 스스로 움직이는 듯한 밝은 별을 보고 고향의 산 정상에 있는 점성탑으로 향했다고 존에게 이야기한다. 마법 그 자체를 즐기는 마음을 중요하게 여긴다.","source":"S-15a9e2c59ba5"},{"label":"학문과 수련","value":"점성탑의 의지를 이은 마법사로 자신을 돌아본다. 실무에 매여 마법 이론이 낯설어진 것을 깨닫자 일주일 휴가를 선언하고 다시 공부할 시간을 찾는다.","source":"S-ce822b057b6d"},{"label":"가르치는 방식","value":"잭에게 세계의 끈 이론과 마법의 원리를 설명하고 실제 주문을 연습하게 한다. 이후 연습할 주문과 수인, 자신의 조언을 적은 자료도 챙겨준다.","source":"S-22cb536224a9"},{"label":"동료를 돕는 일","value":"에피메네우스의 생존 소식을 가족에게 알린다. 아들이 찾아온 뒤에도 가족의 요구만으로 결정하지 않고 에피메네우스 자신의 자유의지를 중요하게 말한다.","source":"S-195e708164b5"},{"label":"오래된 인연","value":"클램시를 친구이자 우상, 자신을 모험으로 이끌었던 영웅으로 회상한다. 클램시와 사자회의 단서를 받는 일은 오랫동안 운영을 지탱해온 개인적인 마음까지 흔든다.","source":"S-1e96be16c475"}],"evaluation":[{"title":"안부를 계획으로 바꾸는 실무","text":"마리아가 휴가를 떠나려 하자 목적지와 이동 경로, 믿을 만한 상단을 확인하게 하고 편지를 당부한다. 막연히 조심하라는 말보다 실제로 확인할 항목을 마련하는 방식이다. 스텔라의 돌봄은 일정과 문서, 경로처럼 생활을 지탱하는 구체적인 형태로 자주 나타난다.","source":"S-745e3605ea69"},{"title":"길드를 지키다가 놓친 자신의 마법","text":"오랫동안 서류를 처리하다 마법학개론이 낯설게 느껴지는 순간 큰 충격을 받는다. 스스로를 호되게 평가하는 반응에는 과장된 유머도 있지만, 좋아했던 일을 놓치고 있다는 아쉬움이 분명하다. 휴가를 선언하는 일은 책임을 맡은 사람에게도 자신을 되찾을 시간이 필요함을 드러낸다.","source":"S-ce822b057b6d"},{"title":"다른 마법사의 질문이 다시 켜는 호기심","text":"존과 야식 카레를 먹으며 마법이 수단인지 삶의 목표인지 논쟁한다. 어린 날의 별을 이야기하고 마음속의 별이 무엇인지 묻는 대화는 스텔라가 여전히 마법의 즐거움과 낭만을 원한다는 것을 보여준다. 경험 많은 운영자에게도 아직 답을 찾는 질문이 남아 있다.","source":"S-15a9e2c59ba5"},{"title":"책임이라는 말 뒤에 숨겼던 친밀함","text":"아리차가 떠난 뒤 모카와 친구의 의미를 이야기하며, 더 직접적으로 마음을 표현했어야 했는지 돌아본다. 사람들을 돌보는 의무에 익숙해도 자신이 누군가를 어떻게 좋아하는지 말하는 일은 쉽지 않다. 책임을 잘 수행하는 모습과 관계에 서툰 모습이 같은 사람 안에 있다.","source":"S-9b1369260074"},{"title":"유능한 판단에도 개인의 마음이 끼어든다","text":"사자회 문제에서는 바키르와 클램시에 얽힌 감정 속에서 강경한 대응을 추진한다. 토르번과 에스텔이 위험을 지적하고 사절단을 제안하자 제한된 시간을 허용한다. 언제나 침착한 관리자라기보다 소중한 관계 때문에 흔들리고, 동료의 의견과 조정하며 결정을 내리는 인물로 읽힌다.","source":"S-1e96be16c475"}],"traits":{"social":{"score":3,"text":"존과 식사를 나누며 논쟁과 개인적인 이야기를 이어가고, 잭에게는 시간을 들여 가르친다. 반면 친구라는 감정을 직접 표현하는 데에는 어려움이 있다. 역할이나 공통 관심사에서 시작해 가까워지는 교류가 두드러진다.","source":"S-15a9e2c59ba5","supportingSources":["S-22cb536224a9","S-9b1369260074"]},"emotion":{"score":4,"text":"평소에는 업무와 책임의 말로 감정을 정리하지만, 아리차의 부재나 클램시의 소식에는 그리움과 후회가 강하게 드러난다. 마법을 잊어가는 자신에게도 큰 충격을 받는다. 겉으로 차분한 장면만으로 감정의 영향이 작다고 보기는 어렵다.","source":"S-1e96be16c475","supportingSources":["S-9b1369260074","S-ce822b057b6d"]},"altruism":{"score":4,"text":"동료의 여행이 안전하도록 확인할 사항을 짚어주고, 잭의 연습 자료를 준비한다. 에피메네우스의 가족을 연결하면서도 본인의 뜻을 존중하려 한다. 시간과 실무 능력을 타인의 생활과 선택을 돕는 데 쓴다.","source":"S-745e3605ea69","supportingSources":["S-22cb536224a9","S-195e708164b5"]},"initiative":{"score":5,"text":"가족에게 직접 생존 소식을 알리고 수업과 운영의 결정을 실행한다. 자신의 공부가 밀린 것을 깨달았을 때도 휴가를 선언해 시간을 확보한다. 공동의 문제와 개인의 필요를 구체적인 행동으로 옮기는 힘이 크다.","source":"S-9ac1aab1539b","supportingSources":["S-22cb536224a9","S-ce822b057b6d","S-39cc952fac30"]},"caution":{"score":4,"text":"휴가 경로와 상단의 신뢰성을 확인하는 등 평소 실무에서는 위험을 세심하게 따진다. 다만 사자회 문제에서는 가까운 사람에 대한 감정이 강경 대응으로 이어져 동료들의 제동을 받는다. 안정적인 실무 능력과 흔들릴 수 있는 판단을 함께 반영했다.","source":"S-745e3605ea69","supportingSources":["S-1e96be16c475","S-195e708164b5"]},"bonds":{"score":5,"text":"클램시에 대한 오랜 우정과 그리움을 간직하고, 떠난 아리차에게 표현하지 못한 마음을 돌아본다. 동료의 편지를 기다리고 가족의 생존 소식을 잇는 행동에서도 관계를 오래 유지하려는 마음이 보인다. 표현의 서툶과 유대를 중시하는 정도를 구분해 평가했다.","source":"S-1e96be16c475","supportingSources":["S-9b1369260074","S-745e3605ea69","S-9ac1aab1539b"]}},"relations":[{"name":"존 (마법사)","text":"야식 카레를 함께 먹으며 마법의 즐거움과 앞으로의 목표를 논쟁하는 동료. 스텔라가 자신의 어린 날과 현재의 질문을 꺼내게 한다.","source":"S-15a9e2c59ba5","characterId":"P-79263e0865dd"},{"name":"잭 해리슨","text":"마법의 원리와 주문을 가르치는 상대. 말로 설명하는 데서 끝내지 않고 연습과 자료까지 챙기며 성장을 요구한다.","source":"S-22cb536224a9","characterId":"P-58df75b248fb"},{"name":"모카","text":"아리차의 부재 뒤 친구와 책임감에 관한 속마음을 나눈 상대. 어린 동료의 관점을 들으며 자신의 표현 방식을 돌아본다.","source":"S-9b1369260074","characterId":"P-f400f584340f"},{"name":"마리아 아나이스 에스더","text":"휴가의 이동 방법을 챙기고 편지를 보내라고 당부한 동료. 떠나 있는 동안에도 소식이 이어지기를 바란다.","source":"S-745e3605ea69","characterId":"P-c9505ea97ebc"},{"name":"토르번 팔켄하인","text":"길드의 일을 나누어 맡으며 위기 대응을 함께 의논하는 공격대장. 강경 대응에 반대하는 의견을 받고 사절단을 보낼 시간을 허용한다.","source":"S-1e96be16c475","characterId":"P-7ba611cf90be"}],"scenes":[{"source":"S-ce822b057b6d","text":"낯설어진 마법학개론 앞에서 자신을 돌아보고 휴가를 선언하는 순간."},{"source":"S-39cc952fac30","text":"업무를 나눈 뒤 홍차와 샌드위치 곁에서 다시 펼치는 마법책."},{"source":"S-9b1369260074","text":"모카에게 친구의 의미를 묻고 표현하지 못한 마음을 돌아보는 대화."},{"source":"S-195e708164b5","text":"에피메네우스와 가족의 재회를 돕되 본인의 선택을 중요하게 여기는 작별."},{"source":"S-15a9e2c59ba5","text":"존과 함께 먹는 야식, 마법을 시작하게 한 별과 아직 남아 있는 질문."},{"source":"S-1e96be16c475","text":"오래된 친구의 단서 앞에서 드러나는 그리움과 사절단을 둘러싼 결정."}],"updatedAt":"2026-09-29","asOf":"2026-09-22","sources":["S-39cc952fac30","S-15a9e2c59ba5","S-ce822b057b6d","S-22cb536224a9","S-195e708164b5","S-1e96be16c475","S-745e3605ea69","S-9b1369260074","S-9ac1aab1539b"]},"P-3bbc4a823df9":{"name":"션","updatedAt":"2026-09-30","tagline":"동료가 살아 돌아올 길을 가르치며, 자신도 사람에게 곁을 내주는 법을 배우는 사람.","tags":["능청스러운","가르치며 돌보는","신뢰를 선택하는"],"profileNote":"샤르니르라는 이름으로도 등장하는 션의 기록이다. 숀 카리엔·숀 사우스 풋과는 별개의 인물이다. 전쟁과 어린 시절의 회상은 대화가 기록된 날짜보다 앞선 사건이며, 진행자가 맡은 다른 인물의 행동과 구분해 정리했다.","facts":[{"label":"출신과 성장","value":"북부 헬그린두르에서 자란 샤르니르. 어린 시절 아버지의 가혹한 훈련과 폭력을 겪었다는 회상이 남아 있다. 강한 전사로 보이는 현재의 모습 뒤에 타인에게 쉽게 드러내지 않는 기억이 있다.","source":"S-a72740846b02"},{"label":"기사로서의 이력","value":"자신을 몰락귀족 출신이라고 말하며, 한때 듀플란테스 장원을 하사받은 지주기사였다고 설명한다. 옛 부관이자 대관인 하리에게 영지의 소식을 전하는 편지를 받는다. 현재 소유권에 대해서는 션의 설명과 하리의 편지가 서로 다르다.","source":"S-53ef21358683"},{"label":"전쟁 경험","value":"밀레엄의 전쟁을 회상하며 중앙수비대장, 중기병대의 선봉, 하사관들의 검술교관을 맡았다고 서술한다. 보급과 경계, 훈련을 중시하는 지휘 체계 속에서 일한 경험이 있다.","source":"S-c581cc4a6d67"},{"label":"길드에서의 역할","value":"길드원들의 지휘와 교육에 책임을 느껴 공격대장을 자청한다. 이후 운영 업무를 나눈 기록에서는 모험가 연합 등 대외 업무를 담당하는 인물로 나온다.","source":"S-39cc952fac30"},{"label":"가족","value":"루체는 옛 연인 티아리엘과의 사이에서 태어난 친딸이다. 딘에게 이 사실을 밝히며, 자신도 최근까지 딸의 존재를 몰랐고 티아리엘은 이미 세상을 떠났다고 말한다.","source":"S-53ef21358683"},{"label":"마리우스와의 관계","value":"마리우스를 첫 제자로 받아들인 뒤 연인이 된다. 고백을 받았을 때는 자신이 마흔 중반이며 딸이 있다는 점을 들어 거절하지만, 이후 다시 대화하고 함께하기로 한다.","source":"S-9c050760b1e6"},{"label":"전투와 가르침","value":"검술을 비롯한 다양한 무기와 실전 경험을 갖춘 무인이다. 마리우스와의 대련에서는 상대의 체구에 맞는 거리와 방어, 칼이 맞닿는 감각을 가르치며 유효타를 인정한다.","source":"S-7122ec5d483f"},{"label":"현재의 몸과 생활","value":"왼손을 잃은 뒤 간이 의수를 거쳐 새 의수를 사용한다. 식사 도구를 다룰 만큼 정교하게 움직이지만 감각은 없다고 느끼며, 달라진 몸으로 일상과 전투를 이어간다.","source":"S-259a89931e65"}],"evaluation":[{"title":"자유롭게 떠돌던 사람이 책임을 맡는 이유","text":"길드의 지휘 체계와 동료들의 행동을 보고 누군가는 가르치고 이끌어야 한다며 공격대장에 지원한다. 책임을 부담스러워하지 않느냐는 질문에는 자신이 싫어한 것은 오지랖 넓어 보이는 일이라고 답한다. 이 자리에서 루체의 아버지라는 사실도 공개된다. 길드가 자신이 드나드는 장소에서, 소중한 사람들과 함께 살아갈 곳으로 바뀌는 흐름이 보인다.","source":"S-4946fe0b8414"},{"title":"이기는 법보다 살아 돌아오는 법을 가르치다","text":"마리우스에게 체격의 차이를 고려하고 힘으로 맞서기보다 공격을 흘리는 방법을 익히게 한다. 첫 유효타를 인정하고 훈련을 마친 뒤에는 죽어서 돌아오지 말라고 당부한다. 다만 진검 대련과 거친 말투에서 드러나듯 가르치는 방식은 엄격하다. 애정이 곧 부드러운 교육 방식으로 나타나는 인물은 아니다.","source":"S-7122ec5d483f"},{"title":"뒤늦게 알게 된 딸 앞의 서툰 아버지","text":"루체의 어머니와 나이를 확인한 순간 평소의 능청스러운 태도가 무너지고, 자신이 아버지라고 밝히며 거듭 사과한다. 티아리엘을 떠난 사정과 이후 소식을 찾지 않았던 일도 인정한다. 딸이 돌아서는 것을 막지 못하고 오래 바라보는 장면은, 아버지라는 사실을 안 것과 그 관계를 쌓는 일이 서로 다르다는 것을 보여준다.","source":"S-0582407b4004"},{"title":"자기 상처를 보여주는 일은 여전히 어렵다","text":"루체에게는 손을 잃은 일을 농담처럼 이야기하지만, 마리우스가 돌아오자 부상을 숨기려고 피해 다닌다. 새로운 의수를 찾고 생활을 이어가는 대응력과 별개로, 가까운 사람에게 약한 모습을 알리는 일에는 서툶이 남아 있다. 다른 사람에게 도움을 받으라고 가르치는 선배도 자신의 상처 앞에서는 망설일 수 있다.","source":"S-8ca678b50564"},{"title":"가까워지는 것이 불편해도 따라 나서는 선택","text":"화를 내며 길드를 나선 숀을 따라가 먼저 이야기를 듣는다. 예전에는 사람에게 곁을 주기 싫어 떠돌았다는 지적에도 수긍하지만, 지금은 동료들이 스스로 포기하지 않는 한 계속 가르치겠다고 말한다. 신입들의 문제를 가볍게 보지는 않으면서도, 관계를 끊기 전에 자신이 할 일을 남겨두는 쪽으로 태도가 바뀐다.","source":"S-30114b2c856b"},{"title":"위험 앞에서 선택하는 믿음","text":"티아멧의 유해를 찾고 돌아온 뒤, 죽은 이를 위해 살아 있는 사람이 위험을 감수하는 일을 아카쿠와 이야기한다. 션은 죽음을 각오했다기보다 함께 싸우는 동료를 믿었다고 설명한다. 결과를 확신할 수 없고 자신도 늘 남을 믿지는 못한다는 점까지 인정한다. 그의 신뢰는 위험이 없다는 판단보다, 불확실한 순간에 누구와 함께 설 것인가에 관한 선택에 가깝다.","source":"S-7ac67eae8ee4"}],"traits":{"social":{"score":4,"text":"농담으로 말을 걸고, 화가 나 떠나는 숀을 따라가거나 아카쿠의 고민을 듣는 등 대화의 접점을 먼저 만든다. 다만 스스로도 가까워지는 것을 피했던 시기를 인정하며, 거친 농담이 누구에게나 편안한 것은 아니다. 쉽게 대화하는 능력과 깊이 곁을 내주는 어려움을 함께 읽었다.","source":"S-30114b2c856b","supportingSources":["S-7ac67eae8ee4","S-2f903333f52b"]},"emotion":{"score":4,"text":"평소에는 장난과 능청스러운 말로 감정을 감추지만, 루체가 친딸임을 알게 되자 크게 동요하고 사과한다. 마리우스에게 부상을 숨기거나 동료를 잃은 뒤 신뢰를 이야기하는 장면에서도 애정과 상실이 행동을 움직인다. 표현을 눌러두는 것과 감정의 영향이 작은 것은 구분했다.","source":"S-0582407b4004","supportingSources":["S-8ca678b50564","S-7ac67eae8ee4"]},"altruism":{"score":4,"text":"동료의 검술을 가르치고 고아원을 방문하며, 길드원이 숲에서 길을 잃지 않도록 울타리를 직접 만든다. 도움은 위기 속의 전투뿐 아니라 반복되는 교육과 생활의 수고로도 나타난다. 엄격한 판단과 거친 언행도 있어 언제나 다정하게 받아주는 인물로 보지는 않았다.","source":"S-37be20581475","supportingSources":["S-7122ec5d483f","S-726de945e654","S-b8ac904d6442"]},"initiative":{"score":5,"text":"공격대장에 먼저 지원하고 훈련과 생활 문제를 직접 손본다. 토르번에게는 길드 대표로 나가 지휘 경험을 쌓을 기회를 권한다. 자신이 앞장서는 것뿐 아니라 다른 사람이 역할을 맡도록 방향을 정하는 주도성도 있다.","source":"S-4946fe0b8414","supportingSources":["S-37be20581475","S-9e680c435366","S-7122ec5d483f"]},"caution":{"score":4,"text":"입회를 원하는 엘레나에게 모험의 부상과 죽음, 다른 동료에게 미칠 책임을 구체적으로 설명한다. 싸움의 승패도 힘만이 아니라 상황과 전략에 달렸다고 본다. 다만 자기 부상은 숨기고 중요한 순간에는 동료를 믿으며 위험에 나서는 면이 있어, 언제나 안전을 최우선으로 고르는 성향은 아니다.","source":"S-b8ac904d6442","supportingSources":["S-1c64575c73ba","S-8ca678b50564","S-7ac67eae8ee4"]},"bonds":{"score":5,"text":"루체에게 책과 고향의 말을 가르치며 뒤늦게 시작한 부녀의 일상을 쌓는다. 마리우스와 함께할 시간을 약속하고, 떠나려는 숀을 찾아가며, 티아멧의 유해를 되찾은 경험도 오래 이야기한다. 가까운 사람을 붙잡고 기억하며 관계를 이어가는 일이 현재의 선택에서 큰 비중을 차지한다.","source":"S-407e4ad91cf4","supportingSources":["S-52bdfe838e84","S-9c050760b1e6","S-30114b2c856b","S-7ac67eae8ee4"]}},"relations":[{"name":"루체 루멘","text":"티아리엘과의 사이에서 태어났지만 뒤늦게 존재를 알게 된 친딸. 책을 읽어주고 용돈을 약속하는 일상 속에서 아버지와 딸로 함께하는 시간을 쌓는다.","source":"S-407e4ad91cf4","characterId":"P-d8e7afee7c51"},{"name":"마리우스","text":"검술을 가르치는 첫 제자이자 연인. 처음의 거절과 다시 나눈 대화를 거쳐 함께하기로 하며, 스승으로서의 책임과 개인적인 애정이 겹친다.","source":"S-9c050760b1e6","characterId":"P-b6d81d634c6e"},{"name":"라이아흐 아카쿠","text":"티아멧을 찾는 여정 뒤 삶의 가치와 신뢰를 논한 친구. 서로의 생각이 다름을 인정하면서 함께 위험을 감수한 이유를 풀어간다.","source":"S-7ac67eae8ee4","characterId":"P-96ab98d2591c"},{"name":"숀","text":"이름이 비슷하지만 별개의 동료. 길드에 실망해 떠나려는 숀을 따라가, 신입을 가르치는 일과 등을 맡길 수 있는 믿음에 관해 이야기한다.","source":"S-30114b2c856b","characterId":"P-5c88d36f51cd"},{"name":"토르번 팔켄하인","text":"운영과 지휘를 나누어 맡는 동료. 길드 대표로 나설 기회를 권하며 사람을 이끄는 경험을 쌓도록 밀어준다.","source":"S-9e680c435366","characterId":"P-7ba611cf90be"},{"name":"스텔라 스타라이트","text":"공격대장 지원을 받아주고 길드의 책임을 함께 논의한 부길드장. 루체의 존재를 알리는 자리에서도 가족과 운영의 사정이 함께 드러난다.","source":"S-4946fe0b8414","characterId":"P-e6655a038328"},{"name":"티아멧","text":"새 무기를 연습할 때 조언과 농담을 나누던 동료. 길드에서 누가 강한지를 따지는 대화에 상황과 전략의 중요성을 짚어준다.","source":"S-1c64575c73ba","characterId":"P-22fdf8486544"}],"scenes":[{"source":"S-a72740846b02","text":"샤르니르의 어린 시절과 가혹한 아버지에 관한 회상. 현재의 모습 이전에 남은 상처를 보여준다."},{"source":"S-0582407b4004","text":"루체가 친딸이라는 사실을 처음 깨닫고 아버지라고 밝히는 모닥불의 밤."},{"source":"S-7122ec5d483f","text":"마리우스가 첫 유효타를 넣고, 션이 살아 돌아오라고 당부하는 대련."},{"source":"S-4946fe0b8414","text":"공격대장 지원과 부녀 관계의 공개가 함께 이루어지는 봄비의 하루."},{"source":"S-ce784d71660f","text":"손을 잃은 아버지에게 루체가 건네는 나무손과 새 의수를 마련할 계획."},{"source":"S-20364a689e31","text":"티아멧의 무기에서 행방을 추적해 유해를 되찾는 칼잡이의 노래."},{"source":"S-407e4ad91cf4","text":"모험이 담긴 책을 딸에게 읽어주며 다시 일상으로 이어지는 이야기."}],"asOf":"2026-09-24","sources":["S-a72740846b02","S-53ef21358683","S-c581cc4a6d67","S-39cc952fac30","S-9c050760b1e6","S-7122ec5d483f","S-259a89931e65","S-4946fe0b8414","S-0582407b4004","S-8ca678b50564","S-30114b2c856b","S-7ac67eae8ee4","S-2f903333f52b","S-37be20581475","S-726de945e654","S-b8ac904d6442","S-9e680c435366","S-1c64575c73ba","S-407e4ad91cf4","S-52bdfe838e84","S-ce784d71660f","S-20364a689e31"]},"P-558bf53bd08b":{"name":"린토와인드 크라우베드","updatedAt":"2026-10-01","mode":"stories","tagline":"옛 동료를 그리워하고, 새로운 모험가에게 선한 의지를 이야기한 검객.","tags":[],"profileNote":"직접 등장한 두 기록만 확인되어 지속적인 성격과 성향을 분석하기는 어렵다. 아래에는 등장 장면에서 확인되는 정보와 이야기만 정리했다. 성향 점수와 핵심 성향은 부여하지 않았다.","facts":[{"label":"이름","value":"길드를 찾아왔을 때는 린토 크라우베드로 서술되고, 술자리에서는 자신을 린토와인드 크라우베드라고 소개한다.","source":"S-3e59f21bc371"},{"label":"모습","value":"페디안을 찾아온 장면에서는 보라색 벨벳 망토를 걸친 해골 모습의 언리빙으로 묘사된다.","source":"S-635e24afaa2b"},{"label":"출신과 나이","value":"남부에서 태어나 어린 시절 중부로 옮겼다고 말한다. 현재 연도를 물어본 뒤 술자리에서 계산한 나이는 백마흔다섯이다.","source":"S-3e59f21bc371"},{"label":"지난 모험","value":"클램시를 따라 모험했다고 회상한다. 서술자는 일곱 영웅 중에서도 강한 의지를 지녔으며 선함을 추구한 검객으로 소개한다.","source":"S-3e59f21bc371"}],"evaluation":[],"traits":{},"relations":[{"name":"페디안 1세","text":"모닥불에 찾아와 젊은이들을 겁주지 말라고 말을 건넨 옛 동료. 변하지 않은 길드를 둘러본 뒤 그의 어깨에 손을 얹고 떠난다.","source":"S-635e24afaa2b","characterId":"P-53bbaf9d6e52"},{"name":"델타인","text":"좋은 친구를 사귀고 있는지 묻고, 무엇이 선한지 고민하는 대화를 나눈다. 델타인을 여전히 좋아하고 싶다는 마음을 의지의 예로 들어 설명한다.","source":"S-3e59f21bc371","characterId":"P-c93f55c91873"},{"name":"거베라 데이시","text":"술자리에서 이름과 출신을 소개하며 만난 인물. 거베라에게 잔을 권하고 서로의 이야기를 듣는다.","source":"S-3e59f21bc371","characterId":"P-2a0e01fe8908"}],"scenes":[{"source":"S-635e24afaa2b","text":"페디안의 모닥불에 잠시 들른 린토는 오래된 길드를 바라본다. 떠나기 전 스텔라의 얼굴을 한 번 봤으면 좋았겠다고 말한다. 이 장면에서 스텔라와 실제로 재회한 것은 아니다."},{"source":"S-3e59f21bc371","text":"거베라와 동료들에게 술을 권하며 자기소개를 한다. 대화는 고향과 나이, 클램시의 모험으로 이어지고, 델타인에게 유명해서 용감한 것이 아니라 용감하게 살아 이름을 남기는 것이라는 취지로 조언한다. 선악에 관한 질문에는 상황과 자신이 바라는 것을 살피라고 답한다."}],"asOf":"2026-08-22","sources":["S-3e59f21bc371","S-635e24afaa2b"]},"P-7ca1485d4525":{"name":"바키르 리온하르트","updatedAt":"2026-10-01","tagline":"함께 살아남는 법을 가르치고, 자유로운 선택으로 동료의 곁을 지키는 노련한 사자.","tags":["협동을 가르치는","사려 깊은","동료를 아끼는"],"profileNote":"바키르가 직접 말하거나 행동한 장면을 중심으로 정리했다. 같은 프로필이 진행한 훈련의 적군·다른 동료들의 행동은 바키르의 성격 근거로 삼지 않았다. 공격대장 직책은 해당 시점의 기록이다.","facts":[{"label":"길드에서의 역할","value":"전쟁 준비 훈련에서 어설픈 용맹의 공격대장으로 소개된다. 사자회의 젊은 사자들을 데려와 길드원들과 합동 훈련을 진행한다.","source":"S-d5208e350565"},{"label":"전쟁 이후의 생활","value":"전쟁 뒤 사자회에서 젊은 사자들을 가르쳤다고 말한다. 에레모시스와는 전쟁에서 서로 다른 편에 섰지만, 개인적인 증오로 싸웠던 것은 아니라고 돌아본다.","source":"S-4e5e48794fe9"},{"label":"길드에 온 이유","value":"클램시가 남긴 것을 지켜달라는 스텔라의 편지를 받고 길드에 왔다. 함께 지내며 길드원들이 좋아졌고, 이제는 자신만의 이유로 이들을 지키고 싶다고 설명한다.","source":"S-4e5e48794fe9"},{"label":"대외 업무","value":"길드의 사절로 조합 회의에 출석하고 정세를 전한다. 전쟁에 인원을 보내야 할 가능성을 옛 전우들과 의논하고, 논의 내용을 스텔라에게 문서로 전달한다.","source":"S-41c4ebe066e0"},{"label":"대장간","value":"직접 풀무질과 단조를 한다. 쇠의 상태를 살피며 반복해서 달구고 두드리는 일에 익숙하고, 그 부지런한 작업 속에서 삶의 자세를 생각한다.","source":"S-15896c086c5d"},{"label":"휴식과 취미","value":"새해 모닥불에서 폴라리스의 옛 이야기를 기억하며 합주를 제안하고 피리를 분다. 서툰 합주도 즐거워하며 잠시 행정 일을 잊는다.","source":"S-633df491d0a9"},{"label":"이후의 행방","value":"8월에 숀은 사자회 간부들이 죽었다는 소문을 근거로 바키르도 죽은 것 같다고 션에게 말한다. 숀 스스로도 정확하지 않다고 덧붙이므로, 이 대화만으로 사망을 확정하지 않았다.","source":"S-30114b2c856b"}],"evaluation":[{"title":"내 방패만으로는 살아남을 수 없다","text":"각자 다른 방패를 가져온 길드원들에게 먼저 서로 의논하지 않은 점을 지적한다. 방패의 모양부터 높이, 보폭까지 옆 사람과 맞추게 하는 훈련은 전투 실력의 합만으로 공동체가 움직이지 않는다는 것을 보여준다. 엄격한 말투의 목적은 개인의 멋진 승리보다 동료가 함께 살아남는 데 있다.","source":"S-d5208e350565"},{"title":"과거의 적과도 선택을 존중하며 함께 서다","text":"에레모시스가 클램시에게서 신성을 이야기할 때 바키르는 한 인간이 스스로 내린 선택을 본다. 같은 영웅을 다른 방식으로 기억해도 신앙을 통일하려 하지 않는다. 서로 적이었던 과거를 지운 것이 아니라, 현재 무엇을 지킬지 각자 고른다는 점에서 동행의 이유를 찾는다.","source":"S-4e5e48794fe9"},{"title":"강한 사람과 전장에 보낼 사람을 구분하다","text":"전쟁에 차출할 인원을 논할 때 나이, 경험, 체격과 대형, 지휘할 사람을 차례로 살핀다. 아이다가 어리다는 점도 짚는다. 유능한 모험가라는 이유만으로 전쟁에 적합하다고 판단하지 않으며, 결정권자에게 논의를 넘기는 절차도 지킨다.","source":"S-41c4ebe066e0"},{"title":"실패해도 되는 자리의 가치를 아는 선배","text":"훈련에서는 전쟁에 다음 시도가 없을 수 있음을 경고하며 지금 시험해 보라고 한다. 새해 합주에서는 완벽하지 않아 즐겁다는 태도로 웃는다. 상황에 맞는 엄격함을 요구하면서도, 배움과 놀이의 실수까지 모두 실패로 취급하지는 않는다.","source":"S-c69c8caba981"},{"title":"부활 앞에서도 멈춰 생각하다","text":"진저가 돌아온 일을 직접 보았지만 테론의 부활에 곧바로 찬성하지는 않는다. 알 수 없는 위험을 이유로 시도를 거부하는 쪽에 선다. 동료를 아끼는 마음과 무엇이든 해보겠다는 행동 사이에 거리를 둘 수 있는 인물이다.","source":"S-c5e3e7fd297d"}],"traits":{"social":{"score":4,"text":"차를 나누며 옛 전우의 안부를 묻고, 새해 모닥불에서는 합주를 먼저 제안한다. 편안한 자리에서 상대의 말을 듣고 교류를 이어가는 장면이 반복된다.","source":"S-633df491d0a9","supportingSources":["S-41c4ebe066e0"]},"emotion":{"score":3,"text":"길드원들이 좋아졌다는 마음과 이루지 못한 평범한 생활의 아쉬움을 담담하게 말한다. 감정을 숨기지는 않지만, 그리움이 곧바로 충동적인 결론으로 이어지지는 않는다.","source":"S-4e5e48794fe9","supportingSources":["S-c5e3e7fd297d"]},"altruism":{"score":4,"text":"동료의 생존을 위해 시간을 들여 훈련시키고, 어린 인물을 전장에 보내는 판단에도 신중하다. 보호의 의지는 추상적인 다짐보다 교육과 배치의 책임으로 나타난다.","source":"S-d5208e350565","supportingSources":["S-41c4ebe066e0"]},"initiative":{"score":4,"text":"훈련을 마련하고 조합에서 얻은 정보를 모아 회담을 연다. 필요한 행동은 먼저 시작하되 길드의 최종 결정을 혼자 대신하지 않는다.","source":"S-41c4ebe066e0","supportingSources":["S-d5208e350565"]},"caution":{"score":5,"text":"전쟁과 개인 전투의 차이를 구체적으로 따지고, 훈련에서 위험을 미리 경험하게 한다. 이미 부활을 본 경험이 있어도 다른 부활의 안전까지 보장된다고 생각하지 않는다.","source":"S-c5e3e7fd297d","supportingSources":["S-41c4ebe066e0","S-d5208e350565"]},"bonds":{"score":4,"text":"클램시의 유산을 지켜달라는 부탁으로 시작한 동행이 현재의 동료들에 대한 애정으로 이어진다. 오래된 전우의 기억과 새롭게 생긴 관계를 함께 소중히 여긴다.","source":"S-4e5e48794fe9","supportingSources":["S-633df491d0a9"]}},"relations":[{"name":"에레모시스","text":"과거 전쟁에서 반대편에 섰던 상대. 클램시를 바라보는 관점은 다르지만, 각자의 자유로운 선택을 인정하며 함께 길드를 지킬 이유를 나눈다.","source":"S-4e5e48794fe9","characterId":"P-d6e0d1eb8b63"},{"name":"폴라리스","text":"이십 년 전부터 이야기를 기억하는 음유시인. 새해의 모닥불에서 무용담과 합주를 즐기며 오랜 기억을 나눈다.","source":"S-633df491d0a9","characterId":"P-5d0c306440d0"},{"name":"션","text":"전쟁에 나설 인원의 조건과 지휘 문제를 함께 논하는 옛 전우. 이 자리의 션은 숀 사우스풋과 다른 인물이다.","source":"S-41c4ebe066e0","characterId":"P-3bbc4a823df9"},{"name":"라이아흐 미샤","text":"방패벽 훈련에서 대형을 정리하고 명령을 내리는 역할을 맡긴 동료. 실제로 말하고 움직여 보게 하며 협동의 요령을 익히도록 한다.","source":"S-d5208e350565","characterId":"P-41ba4c5736e6"},{"name":"스텔라 스타라이트","text":"테론의 부활 시도를 두고 같은 신중한 입장에 선 동료. 길드의 손실 앞에서도 남은 사람들에게 닥칠 위험을 함께 고려한다.","source":"S-c5e3e7fd297d","characterId":"P-e6655a038328"}],"scenes":[{"source":"S-4e5e48794fe9","text":"에레모시스에게 전쟁 이후의 삶과 길드를 지키고 싶은 이유를 말하는 밤."},{"source":"S-633df491d0a9","text":"폴라리스의 이야기와 서툰 합주를 즐기는 새해 모닥불."},{"source":"S-41c4ebe066e0","text":"전쟁에 보낼 사람과 그들을 이끌 사람을 함께 고민하는 회담."},{"source":"S-d5208e350565","text":"서로 다른 방패를 고른 데서 시작해 함께 보폭을 맞추기까지 이어지는 훈련."},{"source":"S-15896c086c5d","text":"달군 쇠를 부지런히 돌보며 일상 속의 깨달음을 얻는 단조."},{"source":"S-c5e3e7fd297d","text":"테론을 잃은 뒤, 부활의 가능성과 위험을 앞에 두고 내리는 판단."}],"asOf":"2026-08-15","sources":["S-d5208e350565","S-4e5e48794fe9","S-41c4ebe066e0","S-15896c086c5d","S-633df491d0a9","S-30114b2c856b","S-c69c8caba981","S-c5e3e7fd297d"]},"P-c1b3ef30b227":{"name":"안케트와","updatedAt":"2026-10-01","mode":"stories","tagline":"클램시의 계약과 길드의 비밀에 얽혀, 소원 거래와 쿠키 소동 사이를 오가는 악마.","tags":[],"profileNote":"직접 등장한 기록은 네 이야기로 연결했다. 분량에는 진행자의 서술과 다른 인물의 행동이 많이 포함되어 있으며, 계약과 정체도 아직 설명되지 않은 부분이 있다. 지속적인 성격을 점수로 분석하기보다 확인된 이야기와 본인이 밝힌 내용을 구분해 소개한다.","facts":[{"label":"정체와 옛 인연","value":"서술자는 크아킨과 맞서 어설픈 용맹 편에서 싸운 악마로 소개한다. 안케트와 자신도 최초의 일곱 인물 중 하나였다고 말한다. 귀환 당시에는 작고 검은 털뭉치 같은 모습으로 나타난다.","source":"S-1ff6f3a007ea"},{"label":"클램시와의 계약","value":"클램시가 자신의 심장을 가져갔으며 일기를 교환했다고 주장한다. 몸을 되찾을 단서를 찾기 위해 클램시의 방에 들어가려 한다. 이 대화만으로 클램시의 현재 생사나 심장의 행방이 확인된 것은 아니다.","source":"S-1ff6f3a007ea"},{"label":"소원 거래","value":"클램시가 이미 대가를 치렀다고 말하며 한 사람당 하나의 소원을 제시한다. 아카쿠가 인간과 드라고니안 사이에서 아이를 가질 방법을 묻자 불가능하다고 답한다. 질문에 답하는 장면과 모든 소원을 실현하는 능력은 구분할 필요가 있다.","source":"S-1ff6f3a007ea"},{"label":"갈래 세계","value":"이름을 불러 찾는 일행 앞에 나타나 푸른 공간을 갈래 세계라고 설명한다. 그 세계의 주인이 자신을 반기지 않는다며 모습이 사라지는 등, 자유롭게 무엇이든 해결하는 존재로 묘사되지는 않는다.","source":"S-49fb545a282d"}],"evaluation":[],"traits":{},"relations":[{"name":"에레모시스","text":"귀환한 안케트와의 정체를 알아보고 클램시의 방으로 들어가는 것을 경계한다. 옛 사건과 현재의 길드, 소원 거래를 두고 격하게 다툰다.","source":"S-1ff6f3a007ea","characterId":"P-d6e0d1eb8b63"},{"name":"라이아흐 아카쿠","text":"아이를 가질 방법을 소원으로 질문한 상대. 안케트와의 장난스러운 모습과 거대한 악마의 모습이 겹쳐 보이는 대화를 나눈다.","source":"S-1ff6f3a007ea","characterId":"P-96ab98d2591c"},{"name":"루체 루멘","text":"갈래 세계에서 이름을 불러 도움을 구하고, 길드에서는 쿠키를 둘러싸고 다툰다. 서로 다른 사건에서 반복해서 마주한다.","source":"S-49fb545a282d","characterId":"P-d8e7afee7c51"},{"name":"모카","text":"쿠키를 가져가려다 소동이 벌어진 상대. 안케트와는 집의 물건이 모두 자기 것이라고 우기며 가구를 움직인다.","source":"S-546fa49489ac","characterId":"P-f400f584340f"}],"scenes":[{"source":"S-1ff6f3a007ea","text":"길드로 돌아와 클램시를 찾는다. 방에 걸린 마법과 자신의 몸을 이야기하며 길드원들에게 소원을 제안하고, 에레모시스의 불신과 맞선다. 악마의 주장과 길드원들이 기억하는 과거가 충돌하는 이야기다."},{"source":"S-49fb545a282d","text":"똑딱이는 우물에서 갈래 세계로 이어진 사건. 안케트와는 루체에게 돌아가야 한다고 경고하고, 이후 세계의 성격을 설명한다. 귀환 과정에는 델타인과 머독의 행동도 함께 작용한다."},{"source":"S-546fa49489ac","text":"모카의 쿠키를 가져가려다 루체와 실랑이를 벌인다. 서랍과 의자를 움직이고 건물을 떨리게 한 뒤 사라진다. 이후 등장해 소동을 묻는 숀의 대사는 안케트와의 행동이 아니다."},{"source":"S-6cf9541f9b6f","text":"히프노스의 초대로 꿈에 갇힌 루체를 찾는 이야기에서 호출된다. 꿈속 안케트와의 정체를 두고 진행 중 문답이 오간다. 일행이 초대의 계약을 깨뜨리고 돌아오는 과정에 등장하며, 꿈속 묘사를 모두 현실의 확정 설정으로 옮기지는 않았다."}],"asOf":"2026-05-23","sources":["S-1ff6f3a007ea","S-49fb545a282d","S-546fa49489ac","S-6cf9541f9b6f"]},"P-41ba4c5736e6":{"name":"라이아흐 미샤","updatedAt":"2026-10-01","tagline":"자신을 지키며 살아온 드루이드가, 반려자 밖으로 가족의 의미를 넓혀가는 이야기.","tags":["현실적인","관계를 돌보는","자기 선택이 분명한"],"profileNote":"어린 시절의 회상과 길드에서 생활하는 현재를 구분했다. 아케오의 가르침은 미샤의 말과 같지 않으며, 드루이드 수행·생존 경험·반려 관계가 현재의 선택에 어떻게 이어지는지를 읽었다.","facts":[{"label":"종족과 배경","value":"인간으로, 어린 시절 드라고니안 사회에서 아카쿠의 반려인간으로 취급받으며 자랐다. 열두 살의 회상에는 다른 시종들의 괴롭힘과 보호받기 어려웠던 생활이 나온다.","source":"S-9b6c1cd9a44e"},{"label":"드루이드 수련","value":"아케오에게 배우고 여러 지역을 유랑하며 자연과 사회를 함께 관찰했다. 열여섯 무렵의 이야기에서 종족과 문화의 관계, 자신이 속할 곳을 고민한다.","source":"S-dce433af06f4"},{"label":"아카쿠와의 관계","value":"스카일라를 떠나 함께 골기아로 향한 반려자. 서로 다른 차별과 생존 경험을 털어놓고, 아카쿠가 미샤의 외로움도 함께 짊어지겠다고 약속한다.","source":"S-7ab1c252d917"},{"label":"길드에서의 행동","value":"동료의 고민을 듣고 식사에 데려가거나 말동무가 되어주겠다고 한다. 아도니스에게는 가족과의 관계를 달라진 모습으로 다시 맺을 수도 있다고 권한다.","source":"S-96cb07f9f25a"},{"label":"보호와 복수","value":"아카쿠가 습격당하자 간호하면서 가해자의 신상을 알아낸다. 직접 보복할 수 있다고 생각하지만 길드의 존재를 고려해 동료들에게 도움을 청하기로 한다.","source":"S-219ce0b71190"},{"label":"넓어지는 가족","value":"엘라의 장례 뒤, 아카쿠와 스승 이외의 사람을 잃는 일도 자신의 마음을 흔든다는 것을 깨닫는다. 모카의 위로를 받으며 길드에 친구가 생겨가고 있음을 말한다.","source":"S-f215d5fe131a"}],"evaluation":[{"title":"다정함 뒤에 있는 생존의 경험","text":"미샤는 아카쿠를 보살피지만 그 역할만으로 자신을 설명하게 두지 않는다. 사막을 건넌 뒤에는 살인과 차별을 겪어온 자신을 숨기지 않고 이야기한다. 순종적인 보호 대상이었던 과거에서 벗어나, 상대가 자신의 거친 면까지 알아주기를 요구하는 사람이다.","source":"S-7ab1c252d917"},{"title":"언제나 어른이고 싶지는 않다","text":"길드 바닥에 누워 칭찬을 요구하는 장면은 우스우면서도 요구가 분명하다. 책임을 지는 어른이어도 응석부릴 시간이 필요하다는 것이다. 아카쿠를 돌보는 역할이 아닌 미샤 자신에 대한 칭찬을 원한다는 말에서, 타인을 챙기는 사람도 독립된 관심과 휴식을 바란다는 마음이 보인다.","source":"S-06f88fc7d320"},{"title":"정답을 주기보다 곁에 머무르는 상담","text":"아도니스가 변화와 버림받는 일을 두려워하자 당장 목표를 정하거나 가족을 찾아가라고 몰아붙이지 않는다. 쉬어가고 관계를 새로 맺을 가능성을 이야기하며 말동무를 자청한다. 자연을 배운 경험이 사람도 변하며 살아갈 수 있다는 여유로 이어지는 장면이다.","source":"S-96cb07f9f25a"},{"title":"애정이 곧 온순함을 뜻하지는 않는다","text":"아카쿠를 해친 사람들에게 보복하려는 마음과 자신의 살인에 대한 태도를 명확하게 드러낸다. 다만 길드의 규칙과 동료들을 떠올리며 혼자 처리하는 대신 도움을 청한다. 배려와 냉혹한 판단이 공존하고, 관계가 그 행동을 조정하기 시작한다는 점이 중요하다.","source":"S-219ce0b71190"},{"title":"가족이 늘어나면서 생기는 슬픔","text":"엘라를 보내며 이전에는 예상하지 못했던 상실을 느낀다. 아카쿠만 가족이라고 생각하던 경계가 느슨해진 만큼 상처받을 가능성도 커진 것이다. 모카에게 친구가 생긴다고 말하는 장면은 길드에 익숙해졌다는 설명보다 그 변화를 선명하게 보여준다.","source":"S-f215d5fe131a"}],"traits":{"social":{"score":4,"text":"동료를 찾아 식사와 대화를 권하고, 말동무가 되어주겠다고 먼저 제안한다. 늘 밝게 어울리기보다 상대의 상태를 살피며 접점을 만드는 쪽이다.","source":"S-96cb07f9f25a","supportingSources":["S-06f88fc7d320"]},"emotion":{"score":4,"text":"억울했던 과거와 아카쿠에 대한 마음을 직접 말하며, 엘라의 죽음 앞에서는 공허함과 두려움을 느낀다. 평소의 침착함 아래 감정이 보호와 관계의 선택을 강하게 움직인다.","source":"S-f215d5fe131a","supportingSources":["S-7ab1c252d917","S-219ce0b71190"]},"altruism":{"score":4,"text":"반려자를 간호하고 아도니스의 불안을 들으며 시간을 내준다. 도움은 가까운 사람을 중심으로 나타나고, 적대하는 사람에게까지 같은 다정함을 적용하지는 않는다.","source":"S-96cb07f9f25a","supportingSources":["S-219ce0b71190"]},"initiative":{"score":4,"text":"필요한 정보를 직접 모으고 동료에게 의뢰할 방향을 정한다. 작은 휴식도 칭찬을 요청하는 행동으로 만들어내며, 자신이 원하는 대우를 분명히 말한다.","source":"S-219ce0b71190","supportingSources":["S-06f88fc7d320"]},"caution":{"score":4,"text":"위험한 환경에서 상대와 사회의 눈치를 살피며 살아왔고, 보복에 앞서 길드에 미칠 영향을 고민한다. 신중함이 폭력을 꺼린다는 뜻은 아니며, 행동의 조건과 결과를 계산하는 경향으로 평가했다.","source":"S-219ce0b71190","supportingSources":["S-9b6c1cd9a44e"]},"bonds":{"score":5,"text":"아카쿠와 삶을 함께하는 관계가 선택의 중심에 있다. 이후 동료의 죽음을 슬퍼하고 새로운 가족을 받아들이며, 지키고 싶은 관계의 범위가 넓어진다.","source":"S-7ab1c252d917","supportingSources":["S-f215d5fe131a"]}},"relations":[{"name":"라이아흐 아카쿠","text":"함께 스카일라를 떠난 반려자. 보호하고 돌보는 데서 나아가 자신이 겪은 차별과 거친 생존 경험까지 나누며 대등한 동행을 요구한다.","source":"S-7ab1c252d917","characterId":"P-96ab98d2591c"},{"name":"아도니스","text":"변해가는 자신과 가족에게 버림받을 가능성을 걱정할 때 대화를 나눈 동료. 미샤는 다시 관계를 맺을 가능성과 쉬어갈 여유를 권한다.","source":"S-96cb07f9f25a","characterId":"P-6eeed2b4661f"},{"name":"모카","text":"엘라의 장례 뒤 토끼풀을 건네 위로한 동료. 미샤가 길드에서 새롭게 생긴 애착을 인정하는 순간을 함께한다.","source":"S-f215d5fe131a","characterId":"P-f400f584340f"},{"name":"하일로 조바","text":"길드 바닥에 누운 미샤와 어른의 책임을 이야기한 상대. 책임을 지면서도 응석부릴 수 있는지 묻는 일상의 대화가 남아 있다.","source":"S-06f88fc7d320","characterId":"P-f6ccefd2c259"},{"name":"아리차","text":"미샤에게 스스로를 돌아보는 태도를 칭찬해 준 동료. 미샤도 아리차가 남몰래 길드원들의 물건을 챙기는 행동을 알아보고 말한다.","source":"S-06f88fc7d320","characterId":"P-0322eff604c2"}],"scenes":[{"source":"S-9b6c1cd9a44e","text":"괴롭힘을 피해 달아난 열두 살 미샤가 아케오를 만나는 날."},{"source":"S-dce433af06f4","text":"유랑 수련과 아카쿠를 향한 마음, 인간 역시 자연의 일부라는 질문."},{"source":"S-7ab1c252d917","text":"사막의 첫 살인 뒤, 감춰졌던 차별과 외로움을 나누는 두 사람."},{"source":"S-06f88fc7d320","text":"책임지는 어른도 칭찬받고 쉬고 싶다는 길드 바닥의 작은 반항."},{"source":"S-219ce0b71190","text":"보복하려는 마음과 길드의 규칙 사이에서 동료에게 도움을 청하기로 하는 밤."},{"source":"S-f215d5fe131a","text":"엘라의 장례 뒤 길드에도 가족 같은 이들이 생겼음을 깨닫는 시간."}],"asOf":"2026-06-26","sources":["S-9b6c1cd9a44e","S-dce433af06f4","S-7ab1c252d917","S-96cb07f9f25a","S-219ce0b71190","S-f215d5fe131a","S-06f88fc7d320"]},"P-92738ae601c0":{"name":"머챈트 마이아","updatedAt":"2026-10-01","tagline":"남의 마음을 생활 속에서 돌보면서, 자신의 그리움과 흔들림도 놓아보려는 상인.","tags":["친근한","생활로 돌보는","그리움을 간직한"],"profileNote":"머챈트·마이아·마이어 표기로 등장한 동일 인물의 기록을 정리했다. 남에게 건네는 성숙한 조언뿐 아니라 무리한 거래와 전투 뒤의 두려움도 함께 반영했다. 손 떨림에 임의의 의학적 진단을 붙이지 않았다.","facts":[{"label":"생업","value":"상업지구에서 활동하며 자기 사업자금을 운용하는 상인. 쓰리스타 채권을 사는 이야기에서는 사업자금을 담보로 빌린 돈까지 투자한다.","source":"S-08395d0222da"},{"label":"가족과 과거","value":"전쟁으로 가족을 잃고 가족을 찾으며 여러 일을 했다고 진저에게 말한다. 어릴 때는 위험을 피하려 남장을 했으며, 지금은 어설픈 용맹을 새로운 가족으로 받아들인다.","source":"S-fbf4efe527ad"},{"label":"길드 업무","value":"스텔라가 휴가로 자리를 비운 동안 부길드장 직무를 대행했다. 익숙하지 않은 서류를 처리하고 폴라리스의 휴가 신청을 받는다.","source":"S-27c0a9d1c80d"},{"label":"손재주와 생활","value":"실과 바늘을 가지고 다니며 아도니스의 돌고래 인형을 꿰매준다. 물건을 고치는 일에 기억과 관계의 의미를 담아 이야기한다.","source":"S-6e662f70b831"},{"label":"생일","value":"션에게 생일 선물로 금연 파이프를 건네며 자신의 생일은 10월 17일이라고 말한다.","source":"S-a4eb77cbe063"},{"label":"전투 이후","value":"하마이잔의 트롤 전투 뒤 피아노를 칠 때 손끝이 떨린다. 의사를 찾아가야겠다고 이야기하면서도 일하러 돌아간다.","source":"S-37c38d208e0e"}],"evaluation":[{"title":"상대가 지금 할 수 있는 일부터 돕다","text":"편지를 못 쓰는 하일로에게 멋진 작품을 쓰려 하지 말고 눈앞의 풍경과 마음부터 적어보라고 한다. 감정을 대신 규정하기보다 본인의 말로 표현할 발판을 마련한다. 장난스러운 놀림과 실질적인 도움이 한 대화 안에서 자연스럽게 이어진다.","source":"S-58aa7a9520f8"},{"title":"배려를 물건으로 건네는 사람","text":"몸이 달라진 티아멧에게 속옷과 리넨을 챙겨주며 당황할 수 있는 생활의 변화를 설명한다. 상대를 구경거리로 삼기보다 실제로 필요한 준비를 떠올리고, 자기답게 지내기를 바란다. 머챈트의 다정함에는 생활을 직접 겪어본 사람의 구체성이 있다.","source":"S-9f8ed85097f2"},{"title":"현명한 조언과 흔들리는 자기 판단","text":"다른 사람의 고민에는 차분하게 조언하지만, 자신의 채권 가격이 떨어지자 더 싸게 살 기회라며 빚을 늘린다. 유능한 상인이라는 인상이 모든 판단의 안전을 보장하지는 않는다. 이 과장된 소동은 기대와 불안을 다루는 데에는 그 역시 허술할 수 있음을 드러낸다.","source":"S-08395d0222da"},{"title":"수선하면서 기억을 붙잡다","text":"처음에는 낡은 인형을 보내주라고 하지만 아도니스의 반응을 보고 직접 고쳐주기로 한다. 이름이 기억을 붙잡는다는 이야기는 추상적인 설교가 아니라 한 땀씩 인형을 꿰매는 행동과 함께 나온다. 자신의 첫 판단보다 상대에게 그 물건이 무엇인지를 다시 살피는 태도가 좋다.","source":"S-6e662f70b831"},{"title":"어른이어도 이별의 답은 모른다","text":"옛 연인의 편지를 태우려다가 미련의 주체가 자신인지 편지인지 고민한다. 어른이란 정답을 아는 사람이 아니라 흔들리며 덜 후회하려 애쓰는 사람이라고 이야기한다. 결국 아이다와 달리며 편지를 바람에 놓는 결말은 그리움을 부정하기보다 작별하는 방식을 스스로 찾는 장면이다.","source":"S-d5d8afd68213"}],"traits":{"social":{"score":5,"text":"먼저 술병을 들고 다가가 농담을 나누거나 막힌 대화에 말을 보탠다. 진저의 과거를 듣고 자신의 경험도 털어놓아 서로 이야기할 수 있는 자리를 만든다.","source":"S-fbf4efe527ad","supportingSources":["S-58aa7a9520f8"]},"emotion":{"score":4,"text":"동료의 출발을 떠올리며 쓸쓸해하고 옛 편지를 쉽게 버리지 못한다. 투자에서는 기대와 불안이 크게 표출되는 등, 감정이 대화와 행동에 분명히 드러난다.","source":"S-d5d8afd68213","supportingSources":["S-75e8e522e6c7","S-08395d0222da"]},"altruism":{"score":4,"text":"인형을 수선하고 필요한 생활용품을 건네며 상대의 표현을 돕는다. 자신의 기술과 시간을 쓰는 반복적인 돌봄이 확인된다.","source":"S-6e662f70b831","supportingSources":["S-9f8ed85097f2","S-58aa7a9520f8"]},"initiative":{"score":4,"text":"필요한 도움을 먼저 제안하고, 낯선 부길드장 대직 업무도 맡아 처리한다. 감정의 정리가 어려운 순간에도 마지막에는 직접 작별의 행동을 택한다.","source":"S-27c0a9d1c80d","supportingSources":["S-d5d8afd68213","S-6e662f70b831"]},"caution":{"score":3,"text":"상대의 생활에서 생길 문제는 미리 챙기지만 자기 투자에서는 소문과 기대에 기대어 위험을 늘린다. 상황에 따라 신중함의 차이가 뚜렷해 하나의 높은 점수로 묶지 않았다.","source":"S-08395d0222da","supportingSources":["S-9f8ed85097f2"]},"bonds":{"score":5,"text":"잃어버린 가족의 빈자리에 길드라는 가족을 받아들이고, 떠나는 동료와 옛 연인을 오래 생각한다. 서로의 이름을 기억하겠다는 약속과 생일 선물에도 관계를 이어가려는 마음이 나타난다.","source":"S-fbf4efe527ad","supportingSources":["S-6e662f70b831","S-d5d8afd68213","S-a4eb77cbe063"]}},"relations":[{"name":"진저브레이브","text":"전쟁과 가족을 잃은 과거를 서로 털어놓은 동료. 농담으로 시작한 모닥불 대화가 새 가족을 받아들였다는 고백으로 이어진다.","source":"S-fbf4efe527ad","characterId":"P-11b5c9c4a5f1"},{"name":"폴라리스","text":"처음 만난 때를 기억하며 휴가 신청을 받는 친구. 대직 중인 머챈트의 책임과 반가움이 함께 드러나는 상대다.","source":"S-27c0a9d1c80d","characterId":"P-5d0c306440d0"},{"name":"하일로 조바","text":"마리아에게 쓸 편지를 어려워할 때 조언한 동료. 거창한 표현보다 지금의 마음을 자기 말로 쓰게 돕는다.","source":"S-58aa7a9520f8","characterId":"P-f6ccefd2c259"},{"name":"티아멧","text":"달라진 몸으로 생활하는 데 필요한 물건과 조언을 건넨 동료. 그 변화 속에서도 자기답게 지내기를 바란다.","source":"S-9f8ed85097f2","characterId":"P-22fdf8486544"},{"name":"아도니스","text":"돌고래 인형을 고쳐주며 서로 이름을 기억하자고 약속한 동료. 작은 물건에 담긴 애착을 존중한다.","source":"S-6e662f70b831","characterId":"P-6eeed2b4661f"},{"name":"스나가와 아이다","text":"이별과 어른의 책임을 이야기하다 함께 숲으로 달린 동료. 편지를 놓아주는 순간을 함께한다.","source":"S-d5d8afd68213","characterId":"P-4a533e2105f8"}],"scenes":[{"source":"S-fbf4efe527ad","text":"진저에게 가족을 잃은 과거와 새 가족이 된 길드를 말하는 모닥불."},{"source":"S-58aa7a9520f8","text":"잘 쓴 작품 대신 마음이 전해지는 편지를 쓰도록 돕는 대화."},{"source":"S-9f8ed85097f2","text":"티아멧에게 생활용품과 자기답게 살아가라는 말을 건네는 빨래터."},{"source":"S-08395d0222da","text":"떨어지는 채권을 할인으로 받아들이며 돈을 더 거는 소동."},{"source":"S-6e662f70b831","text":"돌고래 인형 맥시를 꿰매며 이름과 기억을 이야기하는 시간."},{"source":"S-d5d8afd68213","text":"옛 편지를 태우려던 밤, 아이다와 달리며 바람에 보내는 작별."}],"asOf":"2026-09-07","sources":["S-08395d0222da","S-fbf4efe527ad","S-27c0a9d1c80d","S-6e662f70b831","S-a4eb77cbe063","S-37c38d208e0e","S-58aa7a9520f8","S-9f8ed85097f2","S-d5d8afd68213","S-75e8e522e6c7"]},"P-4a533e2105f8":{"name":"스나가와 아이다","updatedAt":"2026-10-01","tagline":"죽음을 가볍게 뒤집는 세계에 반발하면서도, 살아 있는 동료들과 자신의 이야기를 만드는 소녀.","tags":["죽음을 깊이 생각하는","탐구적인","관계를 배워가는"],"profileNote":"아이다와 스나가와 아이다는 같은 인물이다. 초기의 격한 부활 거부와 이후의 철학적 질문을 모두 담았다. 유령화 능력과 유령이라는 별명을 실제 사망이나 언데드 종족으로 단정하지 않았다.","facts":[{"label":"입회 무렵","value":"돌아가신 어머니에게 쓴 첫 편지에서 열일곱이라고 밝힌다. 어머니의 무덤을 가꾸던 생활을 떠나 길드에 들어왔으며, 사람과 이야기하거나 편지를 쓰는 일이 아직 낯설다고 말한다.","source":"S-fb18ba8397d3"},{"label":"유령화","value":"몸을 투명하게 하거나 물체를 통과하는 모습을 보인다. 다락방 이야기의 서술은 실제 유령은 아니라고 구분한다.","source":"S-ba459d7cb73a"},{"label":"무기","value":"삽을 무기로 사용한다. 처음에는 먹고살기 위해 들었지만 이후 임무를 위해 휘둘렀다고 돌아보며, 새 삽을 어떤 용도로 쓸지 고민한다.","source":"S-e6786249352d"},{"label":"흑주술에 대한 관심","value":"배블스에게 어떤 존재에게 힘을 받았는지, 어떤 계기로 흑마법을 쓰게 됐는지 묻는다. 모호한 답에도 탐구하고 싶다며 질문을 이어간다.","source":"S-ba7d88a56d6f"},{"label":"조사와 공부","value":"도리안의 후견자에 관한 정보를 찾으려고 책과 자료를 뒤진다. 성과가 없자 본가에 편지를 쓰는 다른 접근을 택한다.","source":"S-399dbb7649db"},{"label":"일상의 연습","value":"케이크 만들기에 실패한 뒤 몰래 요리를 연습하고, 직접 만든 초콜릿을 누군가에게 전한다. 받은 사람이 누구인지는 기록에 공개되지 않는다.","source":"S-403d34a88c18"}],"evaluation":[{"title":"부활을 미워하는 마음의 출발점","text":"진저가 돌아오자 자신이 묻은 이들도 누군가에게 소중했다는 생각에 분노한다. 어머니는 돌아오지 않았는데 다른 사람에게는 기적이 허락되었다는 불공평함이 실제 공격으로 이어진다. 상실을 이해하는 것과 그 공격을 정당화하는 것은 별개이며, 이 장면은 아이다가 그 감정을 위험하게 표출한 초기의 모습을 보여준다.","source":"S-ea2ae8e0f6a1"},{"title":"분노가 사라지지 않은 채 질문은 깊어진다","text":"마리아가 되살아난 뒤에는 돌아온 존재가 같은 이름을 이어받아도 되는지, 기억으로 달라진 이야기가 원래의 사람인지 묻는다. 어머니가 돌아와도 같은 질문이 남는다고 생각한다. 부활을 쉽게 받아들이게 됐다고 정리할 수는 없지만, 반감에 정체성과 기억의 문제가 더해지는 변화가 있다.","source":"S-66fd5ba99930"},{"title":"자신과 닮은 고립을 알아보다","text":"다락방의 데이지에게 장난을 걸다가 빵만 먹고 숨어 지낸다는 사정을 듣고 함께 먹고 운동하자고 권한다. 자신의 길드 생활에서 배운 것을 다른 사람에게 돌려주는 모습이다. 다소 짓궂게 밖으로 끌어내려 하면서도 마지막에는 안아도 되는지 묻고 친구가 생긴 것을 기뻐한다.","source":"S-ba459d7cb73a"},{"title":"모르는 것을 그냥 두기 어렵다","text":"흑마법의 힘을 어디서 얻는지 따져 묻고, 단서가 부족한 후견자 조사에서도 다른 경로를 찾는다. 탐구에는 순수한 호기심과 자신에게 일어나는 일을 이해하려는 욕구가 함께 있다. 다만 가설을 말하거나 편지를 쓰는 단계가 곧 수수께끼의 해결을 뜻하지는 않는다.","source":"S-399dbb7649db"},{"title":"혼자였던 인물이 동료에게 느끼는 고마움","text":"입회 초기에는 사람들과 말을 섞는 것도 낯설다고 했지만, 별을 보며 누군가와 만났기 때문에 이야기가 생긴다고 생각하게 된다. 동료들에게 고마움을 전하고 싶다는 독백은 모든 갈등을 극복했다는 결말이 아니다. 그럼에도 현재의 길드 생활을 좋아하고, 관계 속의 자신을 상상하게 된 변화는 분명하다.","source":"S-0041a65e4a82"}],"traits":{"social":{"score":3,"text":"처음에는 말을 섞는 일이 낯설다고 하지만 데이지를 찾아가 이름을 묻고 함께 외출하자고 권한다. 적극적인 장난과 낯가림이 함께 남아 있는, 배워가는 사교성으로 보았다.","source":"S-ba459d7cb73a","supportingSources":["S-fb18ba8397d3"]},"emotion":{"score":5,"text":"어머니를 잃은 마음과 부활의 불공평함이 공격적인 행동까지 이끌며, 이후에도 죽음과 기억을 생각하는 중심에 그리움이 있다. 겉으로 담담한 독백에서도 감정의 영향이 크다.","source":"S-ea2ae8e0f6a1","supportingSources":["S-66fd5ba99930"]},"altruism":{"score":3,"text":"데이지의 식사와 건강을 챙기고 다른 사람을 위해 요리를 연습한다. 동시에 진저에게는 자신의 상처에서 나온 적대감을 가하므로, 가까운 이에게 보이는 배려를 보편적인 헌신으로 넓히지 않았다.","source":"S-ba459d7cb73a","supportingSources":["S-403d34a88c18","S-ea2ae8e0f6a1"]},"initiative":{"score":4,"text":"소문을 직접 확인하러 가고 흑주술의 단서를 조사한다. 원하는 무기를 찾거나 편지를 쓰는 등 궁금증과 필요를 실제 행동으로 옮긴다.","source":"S-399dbb7649db","supportingSources":["S-e6786249352d","S-ba459d7cb73a"]},"caution":{"score":3,"text":"정보가 부족할 때는 질문하고 조사 경로를 바꾸지만, 죽음과 관련된 감정 앞에서는 위험한 행동에 나서기도 한다. 학구적인 생각의 깊이와 행동의 신중함을 같은 것으로 보지는 않았다.","source":"S-ba7d88a56d6f","supportingSources":["S-399dbb7649db","S-ea2ae8e0f6a1"]},"bonds":{"score":4,"text":"어머니를 계속 기억하고 자신의 삶을 그 기억과 연결한다. 이후에는 친구를 사귀고 동료 덕분에 자기 이야기가 생겼다고 느끼며, 길드라는 현재의 관계에도 애착을 갖는다.","source":"S-0041a65e4a82","supportingSources":["S-fb18ba8397d3","S-ba459d7cb73a","S-056353a983bb"]}},"relations":[{"name":"진저브레이브","text":"부활을 받아들이지 못해 공격했던 동료. 아이다의 상실감이 다른 사람과의 갈등으로 드러나는 관계다. 이 사건만으로 이후의 화해까지 단정하지 않았다.","source":"S-ea2ae8e0f6a1","characterId":"P-11b5c9c4a5f1"},{"name":"데이지","text":"다락방에서 찾아낸 뒤 함께 먹고 밖에 나가자고 권한 친구. 고립된 모습을 자신의 예전 모습과 겹쳐 보며 다가간다.","source":"S-ba459d7cb73a","characterId":"P-dec9a5f1b430"},{"name":"코블스톤 크리처 라티오","text":"묘지기의 삽과 나침반을 가공해 아이다의 무기를 만들어 준 동료. 사용하는 도구를 바꾸는 여정의 마지막에 도움을 받는다.","source":"S-0a30de2e6979","characterId":"P-b3929f308454"},{"name":"토르번 팔켄하인","text":"도리안의 죽음과 흑주술에 관해 면담한 동료. 확정되지 않은 가설과 남아 있는 단서를 주고받는다.","source":"S-9fd59966de6c","characterId":"P-7ba611cf90be"},{"name":"머챈트 마이아","text":"그리움과 작별을 이야기하고 함께 숲으로 달린 동료. 머챈트가 옛 편지를 놓아주는 밤을 함께한다.","source":"S-d5d8afd68213","characterId":"P-92738ae601c0"}],"scenes":[{"source":"S-fb18ba8397d3","text":"무덤을 떠나 길드에 들어온 열일곱 아이다가 어머니에게 쓰는 첫 편지."},{"source":"S-ea2ae8e0f6a1","text":"진저의 부활을 받아들이지 못해 삽을 휘두르고 중재를 받는 충돌."},{"source":"S-ba459d7cb73a","text":"다락방의 데이지에게 함께 먹고 운동하자고 권하며 친구가 되는 밤."},{"source":"S-e6786249352d","text":"앞으로 삽을 어떻게 쓸지 생각하며 특별한 무기를 찾는 여정."},{"source":"S-0041a65e4a82","text":"별을 보며 만남이 이야기를 만든다고 생각하고 동료에게 고마워하는 독백."},{"source":"S-66fd5ba99930","text":"되살아난 마리아를 계기로 이름과 기억, 돌아온 사람의 정체성을 묻는 독백."}],"asOf":"2026-09-07","sources":["S-fb18ba8397d3","S-ba459d7cb73a","S-e6786249352d","S-ba7d88a56d6f","S-399dbb7649db","S-403d34a88c18","S-ea2ae8e0f6a1","S-66fd5ba99930","S-0041a65e4a82","S-056353a983bb","S-0a30de2e6979","S-9fd59966de6c","S-d5d8afd68213"]},"P-1ba0b80ec424":{"name":"피에르","updatedAt":"2026-10-01","tagline":"검과 농사에는 익숙하지만 마음을 전하는 일은 서툴러, 동료의 도움으로 한 걸음씩 다가가는 사람.","tags":["순박한","몸으로 실천하는","배움을 시작하는"],"profileNote":"피에르 본인의 행동과 같은 프로필이 맡은 탐정·진행자 등의 역할을 구분했다. 아카쿠와의 첫 만남은 과거 회상이며, 클로에에게 청혼한 기록을 이미 혼례를 마친 상태로 확대하지 않았다.","facts":[{"label":"출신과 이름","value":"스스로 농부라 성이 없다고 소개한다. 부모가 병으로 세상을 떠난 뒤 집과 농지를 잃고 마을을 나와 모험가로 지냈다고 아카쿠에게 이야기한다.","source":"S-113d7bcc34db"},{"label":"검술","value":"재능을 알아본 스승에게 검술을 배웠다고 말한다. 아카쿠와 처음 만난 회상에서는 곰과 싸워 그를 돕고 숲에서 나가는 길을 안내한다.","source":"S-113d7bcc34db"},{"label":"농사와 약초","value":"길드의 밭을 가꾸며 작물과 약초를 구분할 줄 안다. 무를 잡초로 알고 뽑은 모카에게 식물의 차이를 가르친다.","source":"S-b41edec9d71f"},{"label":"글공부","value":"고백 편지를 준비하던 시점에는 글을 읽고 쓰기 어려워 동료들의 도움을 받는다. 다음에는 자기 힘으로 마음을 전할 수 있는 사람이 되고 싶다고 적는다.","source":"S-bfa01050bc9b"},{"label":"클로에와의 관계","value":"깨뜨린 삽을 새로 선물하며 가까워지고, 이후 직접 찾아가 청혼한다. 마음을 받아들인 클로에와 서로를 더 알아가기로 하는 연인 관계로 이어진다.","source":"S-bfa01050bc9b"},{"label":"두려워하는 것","value":"검으로 벨 수 없는 귀신을 특히 두려워한다. 오드리와 밤 숲에 갇힌 사건에서 공포와 혼란을 겪고, 오드리의 도끼에 다친 채 남는다.","source":"S-004cdeda48f4"}],"evaluation":[{"title":"서툰 말투와 실제 능력은 다르다","text":"낯선 종족과 사회의 말에는 익숙하지 않아도 곰의 약점을 알고 싸우며 숲길을 안내한다. 농사와 약초도 자신의 경험으로 다룬다. 피에르의 무지는 모든 분야에 걸친 무능함이 아니라 교육과 경험의 편차로 읽는 것이 정확하다.","source":"S-113d7bcc34db"},{"title":"미안함을 손에 잡히는 선물로 갚다","text":"클로에의 삽을 깨뜨린 일을 잊지 않고 새 삽에 리본을 묶어 찾아간다. 빚은 갚아야 한다는 어머니의 말을 떠올리는 동시에 좋아하는 사람을 만날 구실도 찾는다. 책임감과 설렘이 함께 담긴, 피에르다운 실용적인 선물이다.","source":"S-c6b374fa5d44"},{"title":"도움을 받는 사람에서 스스로 전하는 사람으로","text":"길드원들에게 편지 작성을 맡기면서도 이상한 내용이 들어가지 않는지 확인해 달라고 한다. 결국 자기 마음을 자기 힘으로 전하고 싶다는 바람을 적고 직접 클로에를 찾아간다. 글공부의 필요성이 체면이 아니라 관계를 위해 해주고 싶은 일에서 생긴다는 점이 인상적이다.","source":"S-bfa01050bc9b"},{"title":"무서워도 옆 사람을 먼저 붙잡는 순간","text":"밤 숲에서는 자신이 무너지면 오드리도 무너질 것이라 생각하고 용기를 낸다. 호숫가로 향하는 오드리를 막고 앞장서지만, 이후에는 본인도 공포에 압도된다. 용기는 두려움이 없거나 끝까지 혼자 해결한다는 뜻이 아니라, 무서운 중에도 잠시 타인을 붙드는 행동으로 나타난다.","source":"S-004cdeda48f4"},{"title":"배우는 사람도 가르칠 것은 있다","text":"모카가 밭을 망가뜨리자 크게 화를 내고 끌고 가서 식물을 가르친다. 분명 친절하기만 한 수업은 아니지만, 자기 경험을 전달할 수 있다는 자신감은 뚜렷하다. 글을 모른다는 한 특징만으로 피에르를 늘 가르침을 받는 위치에 두어서는 안 되는 이유다.","source":"S-b41edec9d71f"}],"traits":{"social":{"score":4,"text":"처음 만난 아카쿠의 손을 잡고 함께 식사하며 자기 이야기를 나눈다. 길드에서도 먼저 인사를 건네지만 연애 감정이 앞서는 상대에게는 크게 긴장한다.","source":"S-113d7bcc34db","supportingSources":["S-c6b374fa5d44"]},"emotion":{"score":4,"text":"밭이 망가졌을 때의 분노, 클로에 앞에서의 설렘, 밤 숲의 두려움이 몸과 말에 그대로 나타난다. 감정을 잘 감추는 인물은 아니다.","source":"S-c6b374fa5d44","supportingSources":["S-b41edec9d71f","S-004cdeda48f4"]},"altruism":{"score":4,"text":"위험에 처한 아카쿠를 돕고 길을 안내하며, 자신도 무서운 상황에서 오드리의 안전을 생각한다. 대단한 선언보다는 바로 곁에 있는 사람을 돕는 행동이 근거다.","source":"S-113d7bcc34db","supportingSources":["S-004cdeda48f4"]},"initiative":{"score":4,"text":"새 삽을 준비해 찾아가고 마지막에는 직접 고백한다. 낯선 일에는 도움을 받지만, 필요한 행동까지 다른 사람에게 모두 맡기지는 않는다.","source":"S-bfa01050bc9b","supportingSources":["S-c6b374fa5d44"]},"caution":{"score":3,"text":"경험이 있는 싸움과 숲에서는 위험을 알아차리지만 사회적 거래와 낯선 상황에는 판단이 흔들린다. 편지 내용을 다른 동료에게 확인해 달라고 하는 등 모르는 부분을 보완하려는 행동도 있다.","source":"S-bfa01050bc9b","supportingSources":["S-113d7bcc34db","S-004cdeda48f4"]},"bonds":{"score":4,"text":"어머니의 가르침을 기억하고, 클로에에게 더 많은 것을 해줄 수 있는 사람이 되고자 한다. 동료들의 도움을 떠올려 고백할 용기를 얻는 모습에서도 관계가 행동을 뒷받침한다.","source":"S-bfa01050bc9b","supportingSources":["S-c6b374fa5d44"]}},"relations":[{"name":"클로에","text":"농사와 약초, 선물과 대화를 통해 가까워진 연인. 자기 힘으로 마음을 전하고 싶다는 변화의 중요한 계기가 된다.","source":"S-bfa01050bc9b","characterId":"P-ad57d7b4ca68"},{"name":"라이아흐 아카쿠","text":"과거 숲에서 곰에게 쫓기던 것을 도운 인연. 이후 식사를 함께하며 부모와 고향, 모험가 생활을 이야기한다.","source":"S-113d7bcc34db","characterId":"P-96ab98d2591c"},{"name":"모카","text":"작물을 잡초로 잘못 뽑아 식물 공부를 시킨 상대. 갈등과 교육이 유쾌하면서도 거칠게 겹치는 일상이다.","source":"S-b41edec9d71f","characterId":"P-f400f584340f"},{"name":"오드리","text":"밤 숲의 공포 속에서 서로 의지한 동료. 피에르가 위험을 막아주다가 나중에는 자신도 무너지며, 서로를 위협으로 오인할 만큼 상황이 뒤틀린다.","source":"S-004cdeda48f4","characterId":"P-59654965b99f"},{"name":"존 (마법사)","text":"글을 배우고 직접 마음을 전하도록 조언한 동료. 이 장면의 존은 탐정 존 마커스와 별개다.","source":"S-bfa01050bc9b","characterId":"P-79263e0865dd"},{"name":"핀 머독","text":"편지를 준비하는 모닥불에서 조언한 선배. 다른 동료들과 함께 피에르에게 자신감을 보탠다.","source":"S-bfa01050bc9b","characterId":"P-87b04eb56606"}],"scenes":[{"source":"S-113d7bcc34db","text":"아카쿠를 돕고 고향과 부모, 모험가 생활을 이야기하는 첫 만남의 회상."},{"source":"S-b41edec9d71f","text":"망가진 무밭 앞의 분노가 모카의 식물 공부로 이어지는 소동."},{"source":"S-c6b374fa5d44","text":"리본을 묶은 삽을 선물하고 클로에에게 사랑이 무엇인지 묻는 방문."},{"source":"S-bfa01050bc9b","text":"길드원들의 편지 조언 끝에 직접 마음을 전하고 클로에의 응답을 받는 날."},{"source":"S-004cdeda48f4","text":"용기를 내어 오드리를 돕다가 자신도 공포에 휩싸이는 밤 숲."},{"source":"S-4883e8639520","text":"거베라와 오목을 두며 마법 상추를 심어보자고 이야기하는 일상."}],"asOf":"2026-09-06","sources":["S-113d7bcc34db","S-b41edec9d71f","S-bfa01050bc9b","S-004cdeda48f4","S-c6b374fa5d44","S-4883e8639520"]},"P-5c88d36f51cd":{"name":"숀","updatedAt":"2026-10-01","tagline":"툴툴거리며 거리를 두어도, 동료를 잃는 일을 누구보다 무겁게 받아들이는 작은 검객.","tags":["직설적인","경험으로 가르치는","상실에 민감한"],"profileNote":"숀 사우스풋·숀 사우스 풋·숀 카리엔으로 등장하는 쥐 데미간이다. 인간 검객 션(샤르니르), 별도 캐릭터 카리엔과 합치지 않았다. 마우스가드 시절 이야기는 입회 전의 회상이며 바키르의 죽음은 이 대화 시점에는 확인되지 않은 소문이다.","facts":[{"label":"종족과 이전 소속","value":"쥐 데미간. 어설픈 용맹에 오기 전 마을의 파발대인 마우스가드에서 일했으며, 사자회와 함께 임무를 수행한 경험을 말한다.","source":"S-30114b2c856b"},{"label":"과거의 작별","value":"마우스가드 마지막 임무를 다룬 회상에서 동료들과 폭포를 탈출한다. 함께 출발했던 열둘 중 다섯이 남은 상황에서 은퇴를 선언하고 남은 이들과 서로를 끌어안는다.","source":"S-0ca4cf109c61"},{"label":"길드에 남은 이유","value":"스텔라의 부탁으로 길드원들에게 검을 쥐는 법을 가르치게 됐다고 말한다. 새 동료들의 태도와 실제 전장에서 믿고 싸울 수 있는지를 심각하게 고민한다.","source":"S-30114b2c856b"},{"label":"검술 지도","value":"하일로에게 힘을 빼고 검을 잡는 법, 팔꿈치와 손의 움직임을 가르친다. 낚싯줄을 던지거나 주먹을 쥐는 감각으로 설명하며 몸에 익힐 것을 요구한다.","source":"S-c61348f1a184"},{"label":"일상","value":"숲에 간식을 따로 보관해 두는 장소가 있다. 그곳에서 만난 마리우스의 불안을 듣고, 음식처럼 감정도 쌓아두지 말고 나누라는 말을 건넨다.","source":"S-08db8164bc36"},{"label":"동료 수색","value":"티아멧을 찾기 위해 장비를 갖추고 서쪽으로 떠난다. 피에르에게 행선지와 돌아오겠다는 말을 편지로 남긴다.","source":"S-434fbd22f1a8"}],"evaluation":[{"title":"신뢰를 말하기 전에 생존을 떠올린다","text":"마우스가드 회상에서는 동료의 목숨을 운에 맡기기 싫어 돌파구를 찾고, 결국 자신도 동료의 도움으로 살아난다. 이런 경험을 지닌 숀에게 등을 맡긴다는 말은 가벼운 친목의 표현이 아니다. 길드원들과 전장에 설 자신이 없다는 불만에는 실제 상실에 대한 두려움이 함께 있다.","source":"S-30114b2c856b"},{"title":"거친 말 사이에 생기는 상담의 자리","text":"간식을 숨긴 것이 들켜 당황하면서도 마리우스가 울었다는 것을 알아본다. 션과 자신을 비교하는 조급함을 짚고, 꿈과 남의 말만으로 불안해야 하는 것은 아니라고 말한다. 놀림과 오해도 많지만 결국 상대가 말할 자리를 비워주는 것이 이 대화의 핵심이다.","source":"S-08db8164bc36"},{"title":"남에게 했던 조언이 자신에게는 무겁다","text":"마리우스에게 감정을 털어내라고 말했던 숀은 헬리오스가 떠난 대장간 앞에서 그 말이 쉽지 않음을 느낀다. 먼지를 닦고 다시 오겠다고 하는 작은 행동에는 쉽게 보내지 못하는 마음이 남는다. 조언이 능숙하다고 이별까지 능숙한 인물은 아니다.","source":"S-4db98fd3c08f"},{"title":"쓴소리 끝에 상대의 선택을 남겨둔다","text":"루체에게 칭찬만 듣는 위험을 이야기하지만 무엇을 믿어야 하는지를 대신 정하지는 않는다. 신을 믿는다면 그 선택을 하는 자신도 믿으라고 권한다. 말투는 거칠어도 상대가 자기 판단을 지닐 수 있기를 바라는 가르침이다.","source":"S-83428fdbf92c"},{"title":"도망친 뒤에도 살아갈 방향은 남아 있다","text":"이별 편지를 받고 폴라리스와 이야기하면서 도망치는 일을 무조건 나쁘다고 보지 않는다. 더 잘 살아보려는 반응일 수 있지만 결국 자신에게서 달아날 수는 없다고 말한다. 남을 위로하며 자기 상황도 함께 인정하는 점에서, 숀의 조언은 완성된 정답보다 경험 중인 사람의 말에 가깝다.","source":"S-86aad3711659"}],"traits":{"social":{"score":3,"text":"사람들과 농담하고 고민도 듣지만 지나치게 가까운 관계와 무분별한 말에 피로를 느낀다. 누구에게나 쉽게 곁을 내주기보다 상대와 상황을 고른다.","source":"S-30114b2c856b","supportingSources":["S-08db8164bc36"]},"emotion":{"score":4,"text":"화가 나 길드를 나가고, 떠난 친구의 대장간에서 그리움을 느끼며 이별 편지 앞에서는 괜한 욕도 한다. 무심한 말투와 달리 상실과 불안이 행동에 강하게 드러난다.","source":"S-4db98fd3c08f","supportingSources":["S-30114b2c856b","S-86aad3711659"]},"altruism":{"score":4,"text":"배우겠다는 하일로를 가르치고 울던 마리우스의 이야기를 듣는다. 동료를 찾으러 직접 떠나는 수고도 감수하지만 모든 신입을 무조건 받아주는 태도는 아니다.","source":"S-c61348f1a184","supportingSources":["S-08db8164bc36","S-434fbd22f1a8"]},"initiative":{"score":4,"text":"위기에서 탈출할 방법을 찾고, 검술 수업과 동료 수색을 실제 행동으로 옮긴다. 불만이 쌓이면 직접 자리를 떠나는 등 경계를 정하는 행동도 분명하다.","source":"S-0ca4cf109c61","supportingSources":["S-434fbd22f1a8","S-30114b2c856b"]},"caution":{"score":4,"text":"동료를 운에 맡기지 않으려 하고 전장에서 믿을 수 있는지를 따진다. 바키르에 관한 소문도 확실하지 않으니 퍼뜨리지 말라고 한다. 다만 화가 난 순간의 언행에는 날카로움이 남는다.","source":"S-30114b2c856b","supportingSources":["S-0ca4cf109c61"]},"bonds":{"score":5,"text":"옛 동료의 이름을 기억하고 빈 대장간을 다시 찾으며 티아멧 수색에 나선다. 친밀함이 불편하다고 말하면서도 이미 맺은 인연이 현재의 선택을 크게 움직인다.","source":"S-4db98fd3c08f","supportingSources":["S-0ca4cf109c61","S-434fbd22f1a8"]}},"relations":[{"name":"션","text":"길드를 떠나려는 숀을 따라와 이야기를 들은 인간 검객. 교육과 책임, 동료에게 등을 맡길 믿음을 두고 솔직하게 다툼과 걱정을 나눈다.","source":"S-30114b2c856b","characterId":"P-3bbc4a823df9"},{"name":"마리우스","text":"헬리오스에게 딸 같은 존재이므로 자신에게도 그와 같다고 말한 동료. 숲의 간식 창고에서 연애와 수련의 불안을 듣는다.","source":"S-08db8164bc36","characterId":"P-b6d81d634c6e"},{"name":"루체 루멘","text":"재능을 경계하면서도 자신을 믿는 법을 말해준 어린 동료. 무조건적인 칭찬과 스스로 고른 믿음의 차이를 설명한다.","source":"S-83428fdbf92c","characterId":"P-d8e7afee7c51"},{"name":"하일로 조바","text":"검술을 가르친 동료. 손과 팔의 움직임을 구체적으로 교정하고 반복해서 감각을 익히게 한다.","source":"S-c61348f1a184","characterId":"P-f6ccefd2c259"},{"name":"폴라리스","text":"각자의 연애와 거절, 도망친 이후의 방향을 나눈 친구. 남의 선택을 인정하면서 자기 이별도 털어놓는다.","source":"S-86aad3711659","characterId":"P-5d0c306440d0"},{"name":"린 (길드원)","text":"티아멧 수색길에서 명예와 상실을 이야기한 동료. 아카쿠가 뒤처지면 도와달라고 부탁한다.","source":"S-2c8f392dc137","characterId":"P-deff0d294482"}],"scenes":[{"source":"S-0ca4cf109c61","text":"마우스가드 시절의 폭포 탈출과 은퇴, 동료들의 이름을 남기는 작별."},{"source":"S-08db8164bc36","text":"숨겨둔 간식과 쌓아둔 감정을 나누는 마리우스와의 새벽 대화."},{"source":"S-4db98fd3c08f","text":"헬리오스 없는 대장간에서 조언의 무게를 되돌려 받는 밤."},{"source":"S-83428fdbf92c","text":"루체에게 자기 선택을 믿을 힘을 갖추라고 말하는 훈련장."},{"source":"S-30114b2c856b","text":"화를 내고 길드를 나선 뒤 션에게 불신과 바키르의 소문을 털어놓는 시간."},{"source":"S-434fbd22f1a8","text":"피에르에게 편지를 남기고 티아멧을 찾으러 출발하는 날."}],"asOf":"2026-09-13","sources":["S-30114b2c856b","S-0ca4cf109c61","S-c61348f1a184","S-08db8164bc36","S-434fbd22f1a8","S-4db98fd3c08f","S-83428fdbf92c","S-86aad3711659","S-2c8f392dc137"]},"P-87b04eb56606":{"name":"핀 머독","updatedAt":"2026-10-01","tagline":"큰 웃음과 튼튼한 몸으로 사람을 돕고, 웃음 뒤의 상실도 함께 품고 사는 동료.","tags":["호탕한","행동으로 돕는","상실을 품은"],"profileNote":"머독의 직접 행동과 회상을 중심으로 정리했다. 본인이 말하는 마법 솥과 장수 이야기는 발언의 맥락을 남겼고, 웃긴 장면을 모두 너그러운 배려로 포장하지 않았다.","facts":[{"label":"이름과 나이","value":"핀 머독. 흰 코털을 발견하는 7월의 장면에서 마흔한 살로 소개된다.","source":"S-56bb874bb8ba"},{"label":"힘과 성장","value":"어렸을 때 마법 솥에 빠진 뒤 힘이 달라졌다는 은사의 설명을 전한다. 특별한 운동 없이도 힘이 좋아 짐꾼으로 일하고 싸우며 자랐다고 회상한다.","source":"S-56bb874bb8ba"},{"label":"전투 방식","value":"주로 맨손으로 싸우지만 의자나 책상도 필요에 따라 쓴다고 말한다. 싸움에서는 거리와 상대의 발, 호흡을 살피며 등을 맡길 동료를 중요하게 여긴다.","source":"S-2ea37fcffe10"},{"label":"은사","value":"사잔을 삼백 년 넘게 살아온 인간 드루이드인 은사로 소개한다. 자신에게 마법 솥 이야기를 해주었던 스승이다.","source":"S-56bb874bb8ba"},{"label":"보육원","value":"은사가 마련한 숲의 보육원을 자주 찾아가, 차별로 바깥 생활이 어려운 아이들과 시간을 보낸다.","source":"S-081f7fb3f726"},{"label":"딸의 기억","value":"같은 보육원에서 자신의 딸도 길렀다고 미샤에게 말한다. 딸에게 있었던 병을 회상하며, 아이에게 사랑을 전하던 말을 들려준다.","source":"S-081f7fb3f726"},{"label":"혼인 서약의 증인","value":"피를 흘리며 돌아온 하일로 곁에서 도움을 구하고 마리아의 치유를 지켜본다. 이후 두 사람의 서약을 묻고, 서로 진실하게 약속했음을 증언하며 부부가 되었음을 선언한다.","source":"S-ec1616980738"}],"evaluation":[{"title":"자기 연민까지 돌아보는 돌봄","text":"보육원에서 아이들을 신나게 놀아주지만, 함께 밥을 먹을 때는 자신에게도 동정심이 남아 있음을 인정한다. 오히려 서로를 자연스럽게 받아들이는 아이들에게 배운다고 말한다. 돌보는 사람인 자신을 완벽한 선인으로 놓지 않는 이 고백이 머독의 따뜻함에 깊이를 더한다.","source":"S-081f7fb3f726"},{"title":"사명을 거창한 보상과 바꾸지 않는다","text":"앞에서 싸우는 사람에게 언제나 칭송이 돌아오지는 않으며, 그 일을 해야 할 사람이 하는 것이라고 설명한다. 한편 직접 행동하는 것이 어렵다는 점을 알아보고 존을 응원한다. 자신의 힘을 과시하는 데서 그치지 않고, 다른 방식으로 책임을 맡는 동료의 용기도 인정한다.","source":"S-2ea37fcffe10"},{"title":"위로를 다음 약속으로 이어가다","text":"부상당한 동료들과 냇가에 앉아 오래된 친구와 일상을 이야기하고, 상처가 아물면 함께 꽃구경을 가자고 한다. 잃은 것을 되돌릴 수 있다고 장담하기보다 함께 보낼 시간을 남겨둔다. 거창한 해결책 없이도 관계가 계속된다는 감각을 건네는 방식이다.","source":"S-9c5be8e75504"},{"title":"유쾌함에는 곤란한 장난도 섞인다","text":"잠든 동료들의 문을 두드리며 가짜 공습경보를 외치고 크게 웃는다. 머독의 활력과 장난기가 길드 일상을 만드는 것은 분명하지만, 놀란 사람에게도 편안한 행동은 아니다. 다정한 선배라는 이미지와 타인의 경계를 가볍게 넘는 순간을 함께 보아야 한다.","source":"S-b4e5d288c8e9"},{"title":"축하와 걱정을 한꺼번에 품다","text":"마리아와 하일로의 서약을 이끌면서도 두 사람이 앞으로 받을 시선을 떠올린다. 그 걱정을 결혼을 막는 말로 바꾸지 않고 짧은 축하를 남긴다. 경험으로 예상하는 고통과 당사자들이 고른 행복을 동시에 존중하려는 모습이다.","source":"S-ec1616980738"}],"traits":{"social":{"score":5,"text":"아이들과 몸을 움직여 놀고 동료를 먼저 부르며 함께 밥과 술을 나눈다. 이름을 엉뚱하게 부르고 크게 농담하는 방식은 친근하지만 때로 상대를 당황하게도 한다.","source":"S-081f7fb3f726","supportingSources":["S-b4e5d288c8e9"]},"emotion":{"score":4,"text":"기쁨과 장난을 크게 표현하고, 위독한 하일로 앞에서는 초조함과 안도를 숨기지 못한다. 딸과 오래된 동료에 대한 기억에서는 호탕한 모습 뒤의 슬픔도 드러난다.","source":"S-ec1616980738","supportingSources":["S-081f7fb3f726","S-b38099bf9e25"]},"altruism":{"score":5,"text":"보육원을 반복해서 찾고 동료의 청소를 도우며 위급한 사람에게 달려간다. 한 번의 큰 선언보다 자기 시간과 몸을 꾸준히 쓰는 행동이 근거다.","source":"S-081f7fb3f726","supportingSources":["S-b38099bf9e25","S-ec1616980738"]},"initiative":{"score":4,"text":"필요를 느낀 사람이 먼저 하면 된다고 말하며 동료에게 교육을 제안한다. 부상자들을 밖으로 데려가고 다음 나들이를 약속하는 등 공동의 행동을 시작하는 편이다.","source":"S-2ea37fcffe10","supportingSources":["S-9c5be8e75504"]},"caution":{"score":3,"text":"위급한 출혈과 전투의 조건은 살피지만 일상에서는 요리에 보이는 재료를 모두 넣거나 경보 장난을 벌인다. 경험에서 나온 판단과 즉흥적인 행동이 함께 있다.","source":"S-ec1616980738","supportingSources":["S-000404a1d715","S-b4e5d288c8e9"]},"bonds":{"score":5,"text":"딸과 옛 동료의 이름을 기억하고 보육원과 길드를 가족처럼 돌아본다. 부상 뒤의 나들이, 서로 그리워할 일이 없기를 바라는 농담에도 오래 함께하고 싶은 마음이 담긴다.","source":"S-081f7fb3f726","supportingSources":["S-b38099bf9e25","S-9c5be8e75504"]}},"relations":[{"name":"라이아흐 미샤","text":"보육원을 함께 방문하고 딸의 이야기를 털어놓은 동료. 돌봄과 동정, 가족에 관해 속마음을 나눈다.","source":"S-081f7fb3f726","characterId":"P-41ba4c5736e6"},{"name":"에스텔 벨라시타","text":"각자 부상을 겪은 뒤 냇가에서 함께 시간을 보낸 동료. 상처가 아물면 꽃구경을 가자며 앞으로의 약속을 건넨다.","source":"S-9c5be8e75504","characterId":"P-b522cca806d0"},{"name":"델타인","text":"청소 내기를 하고 오래된 동료들의 안부를 묻는 친구. 장수에 관한 우스갯소리로 서로 헤어질 걱정을 덜어주려 한다.","source":"S-b38099bf9e25","characterId":"P-c93f55c91873"},{"name":"존 (마법사)","text":"길드의 책임과 교육을 논한 동료. 말처럼 행동이 쉽지 않다는 것을 인정하고 먼저 움직이는 용기를 응원한다.","source":"S-2ea37fcffe10","characterId":"P-79263e0865dd"},{"name":"라이아흐 아카쿠","text":"앞에서 싸우는 이의 사명과 동료의 중요성을 이야기한 상대. 힘만이 아니라 등을 맡길 사람이 필요하다고 말한다.","source":"S-2ea37fcffe10","characterId":"P-96ab98d2591c"},{"name":"마리아 아나이스 에스더","text":"하일로를 살리기 위해 치유하는 모습을 곁에서 지켜보고, 이후 혼인 서약을 받은 동료. 기쁨과 앞날의 걱정을 함께 품는다.","source":"S-ec1616980738","characterId":"P-c9505ea97ebc"}],"scenes":[{"source":"S-081f7fb3f726","text":"아이들과 해적놀이를 한 뒤 딸과 돌봄을 이야기하는 보육원의 저녁."},{"source":"S-9c5be8e75504","text":"부상당한 동료들과 냇가에서 앉아 다음 꽃구경을 약속하는 시간."},{"source":"S-b4e5d288c8e9","text":"동료들의 낮잠을 깨우는 가짜 공습경보와 식사 소동."},{"source":"S-56bb874bb8ba","text":"흰 코털 하나에 노화를 고민하며 자신의 성장과 은사를 이야기하는 날."},{"source":"S-2ea37fcffe10","text":"누군가는 해야 할 일을 맡는다는 사명과 동료의 용기를 이야기하는 밤."},{"source":"S-ec1616980738","text":"하일로의 생환을 기뻐하고 마리아와의 서약을 증언하는 순간."}],"asOf":"2026-09-26","sources":["S-56bb874bb8ba","S-2ea37fcffe10","S-081f7fb3f726","S-ec1616980738","S-9c5be8e75504","S-b4e5d288c8e9","S-b38099bf9e25","S-000404a1d715"]},"P-1ebd61bdfafd":{"name":"딘 로안","updatedAt":"2026-10-01","tagline":"대단해지고 싶은 조급함을 안고, 사랑과 배움을 반복되는 노력으로 바꾸기 시작한 청년.","tags":["감정에 솔직한","인정을 갈망하는","노력으로 옮기는"],"profileNote":"딘 로안의 기록이다. 젊은 딘의 현재와 기억 공간의 늙은 딘을 구분했고, 훈련 장면의 “사망·활부”는 어제의 약한 자신을 버린다는 익살스러운 표현으로 읽었다. 스노우가 반지를 받은 사실을 청혼 승낙이나 혼인으로 바꾸지 않았다.","facts":[{"label":"이름과 나이","value":"9월 훈련 장면에서 래빗 풋, 딘 로안으로 소개되며 나이는 스무 살이다.","source":"S-b93795650dcc"},{"label":"마법에 대한 열망","value":"테론의 장례 때 부활을 주장하고, 정식으로 배운 적이 없다고 하면서도 바키르의 노트에서 찾은 주문으로 의식을 시도한다. 서술자는 슬픔뿐 아니라 마법에 대한 갈망과 자격지심도 동기라고 짚는다.","source":"S-c5e3e7fd297d"},{"label":"기억 공간의 사건","value":"솔과 니콜라스는 기억 속 길드에서 늙은 딘을 만난다. 솔이 그를 대신해 남은 뒤 현실로 돌아온 젊은 딘은 사건을 기억하지 못하는 모습이다. 기억 공간의 긴 세월을 현재 육체의 나이로 더하지 않았다.","source":"S-2101b42c14eb"},{"label":"문학 공부","value":"기본적인 읽기와 쓰기는 할 줄 안다. 스노우에게 마음을 전하고 싶어 사이먼을 찾아가, 예쁜 단어를 나열하기보다 자기 마음을 정리하는 문학을 배우겠다고 한다.","source":"S-73732fc8d2b9"},{"label":"훈련","value":"달리기와 맨몸운동을 다시 시작한다. 스스로 오십 일째라고 부르는 훈련에서는 통나무를 끌지 못하지만 붙기 시작한 근육을 확인하고 다시 시도한다.","source":"S-b93795650dcc"},{"label":"스노우에게 준 선물","value":"은반지를 감사의 표시로 건네며 손에 끼지 않아도 된다고 말한다. 좋아하는 마음은 분명히 밝히지만, 이 선물 자체에는 감사 외의 뜻을 담지 않겠다고 설명한다.","source":"S-de4617626822"}],"evaluation":[{"title":"선한 목표에도 자기 욕망이 섞인다","text":"테론을 살려야 한다고 외치는 딘은 동료를 잃은 슬픔과 함께 마법을 가진 사람들에 대한 열등감을 드러낸다. 이해하지 못한 주문으로 일행을 모으는 행동은 적극적이지만 위험하다. 진심을 가진다는 것과 그 진심이 안전하고 타당한 방법을 보장한다는 것은 다르다.","source":"S-c5e3e7fd297d"},{"title":"사랑이 생활을 바꾸는 계기가 되다","text":"스노우에게 반한 뒤 강해지겠다는 다짐은 달리기와 운동, 문학 공부로 이어진다. 거창한 목표와 우스운 실패가 함께 나오지만, 오십 일째에도 통나무에 다시 매달린다. 이미 뛰어난 전사가 됐다는 성과보다 반복해서 돌아오는 습관에서 성장을 읽을 수 있다.","source":"S-b93795650dcc"},{"title":"번지르르한 말보다 자기 마음을 배우려 한다","text":"사이먼에게 글자 대신 문학을 배우고 싶다고 명확히 말한다. 청혼이 목적이지만 예쁜 표현만 얻으려는 것은 아니며, 먼저 자기 감정을 정리하고 싶어한다. 자신에게 부족한 것이 무엇인지 구체적으로 말하고 배움을 요청하는 태도가 이전의 막연한 힘에 대한 갈망과 다른 지점이다.","source":"S-73732fc8d2b9"},{"title":"응답을 바라는 마음과 감사의 구분","text":"반지를 주기 전에는 빠른 연애 전개를 혼자 상상하지만 실제 대화에서는 감사의 표시라고 설명하고 착용을 요구하지 않는다. 반복해서 청혼하겠다는 조급함은 여전히 남아 있다. 그 안에서도 선물을 받은 상대가 부담을 느낄 수 있음을 생각하기 시작한다는 변화가 보인다.","source":"S-de4617626822"},{"title":"웃음이 슬픔을 다 보여주지는 않는다","text":"사이먼의 죽음을 들은 딘은 속으로 약속을 남긴 선배에게 화를 내지만 겉으로는 밝게 웃는다. 시안에게도 낙엽 청소 농담으로 답해 서로의 슬픔을 알아보지 못한다. 표현이 풍부한 인물이라도 감당하기 힘든 상실 앞에서는 마음과 말이 갈라질 수 있다는 장면이다.","source":"S-1a7d7f547838"},{"title":"설득의 실패 뒤에도 남는 질문","text":"우물을 오염시킨 루카에게 남겨둔 해독제를 보이며 스스로와 세상을 용서하라고 설득한다. 설득과 해독 시도가 모두 뜻대로 되지는 않아 사건은 왕국에 넘겨진다. 딘은 귀환길에서 자신들도 같은 고통을 겪으면 무엇으로 견딜지 묻는다. 해결한 영웅담보다 실패 뒤에 남은 질문이 인물을 설명한다.","source":"S-e8ad1cc5cc64"}],"traits":{"social":{"score":4,"text":"선배를 찾아 도움을 청하고 처음 마음이 움직인 상대에게도 적극적으로 다가간다. 다만 들뜬 말과 빠른 청혼이 상대의 속도와 늘 맞는 것은 아니다.","source":"S-73732fc8d2b9","supportingSources":["S-9db8a463da4d","S-de4617626822"]},"emotion":{"score":5,"text":"사랑이 훈련을 다시 시작하게 하고, 열등감이 위험한 의식의 동기가 되며, 상실은 감춘 분노로 남는다. 밝은 표현뿐 아니라 선택을 움직이는 감정의 비중이 크다.","source":"S-c5e3e7fd297d","supportingSources":["S-b93795650dcc","S-1a7d7f547838"]},"altruism":{"score":3,"text":"루카에게 해독제를 내밀고 용서할 길을 찾으려 하지만 테론의 부활 시도에는 자신의 열망도 섞여 있다. 타인을 위하는 마음과 인정받고 싶은 욕구가 공존한다.","source":"S-e8ad1cc5cc64","supportingSources":["S-c5e3e7fd297d"]},"initiative":{"score":5,"text":"동료를 모아 의식을 시도하고, 스스로 공부를 청하며 반복해서 운동한다. 옳은 결과를 보장하는 점수가 아니라 생각을 실제 행동으로 옮기는 빈도와 강도를 나타낸다.","source":"S-73732fc8d2b9","supportingSources":["S-c5e3e7fd297d","S-b93795650dcc"]},"caution":{"score":2,"text":"정체를 충분히 이해하지 못한 주문을 감으로 골라 시도할 만큼 조급하다. 이후 반지가 상대에게 줄 부담을 생각하는 장면도 있지만, 확인한 대표 장면에서는 숙고보다 열망이 먼저 나서는 경향이 강하다.","source":"S-c5e3e7fd297d","supportingSources":["S-de4617626822"]},"bonds":{"score":4,"text":"스노우와의 만남에 삶을 바꾸는 의미를 부여하고, 사이먼과의 배움 약속이 끊기자 크게 흔들린다. 관계에 거는 기대가 높고 그 연결이 자신의 목표를 지탱한다.","source":"S-de4617626822","supportingSources":["S-73732fc8d2b9","S-1a7d7f547838"]}},"relations":[{"name":"스노우 글로우","text":"반한 뒤 훈련과 공부를 다시 시작하게 된 상대. 감사의 반지를 건네지만 이 장면에서 결혼이 성사된 것은 아니다.","source":"S-de4617626822","characterId":"P-2bd2e06457e6"},{"name":"사이먼 피터 포레스트","text":"자기 마음을 표현할 문학을 배우고자 찾아간 선배. 이후 그를 잃었다는 소식은 지켜지지 못한 약속과 분노로 남는다.","source":"S-73732fc8d2b9","characterId":"P-3ea4affc20fd"},{"name":"솔 세크메트","text":"기억 속 길드에서 늙은 딘을 대신해 남기로 선택한 인물. 현재의 딘이 그 사건을 기억하지 못한다는 점까지 함께 보아야 하는 인연이다.","source":"S-2101b42c14eb","characterId":"P-e2f54d3db7fa"},{"name":"션","text":"우물 사건을 함께 조사하고 귀환길에 고통을 견디는 방법을 물은 선배. 훗날 사이먼의 소식도 전해 듣는다.","source":"S-e8ad1cc5cc64","characterId":"P-3bbc4a823df9"},{"name":"시안 던 브링어","text":"사이먼의 죽음을 전해 들은 직후 말을 걸어온 동료. 농담하는 딘의 겉모습 때문에 속에 있는 슬픔이 충분히 전해지지 않는다.","source":"S-1a7d7f547838","characterId":"P-77d4478f4f51"},{"name":"바키르 리온하르트","text":"테론의 부활을 두고 부딪친 선배. 딘은 그의 신중한 판단을 따르지 않고 노트의 주문으로 별도 의식을 시도한다.","source":"S-c5e3e7fd297d","characterId":"P-7ca1485d4525"}],"scenes":[{"source":"S-c5e3e7fd297d","text":"테론을 살리겠다는 주장과 마법에 대한 갈망이 뒤얽힌 부활 시도."},{"source":"S-2101b42c14eb","text":"기억 공간의 늙은 딘과 솔의 선택, 사건을 기억하지 못하는 젊은 딘의 귀환."},{"source":"S-73732fc8d2b9","text":"사이먼에게 글자가 아니라 마음을 정리하는 문학을 배우겠다고 청하는 방문."},{"source":"S-de4617626822","text":"냇가에서 스노우에게 감사의 은반지를 건네는 대화."},{"source":"S-1a7d7f547838","text":"사이먼의 부재를 알게 된 뒤 밝은 말과 속마음이 갈라지는 순간."},{"source":"S-b93795650dcc","text":"끌리지 않는 통나무 앞에서도 다시 시도하는 오십 일째의 훈련."}],"asOf":"2026-09-23","sources":["S-b93795650dcc","S-c5e3e7fd297d","S-2101b42c14eb","S-73732fc8d2b9","S-de4617626822","S-1a7d7f547838","S-e8ad1cc5cc64","S-9db8a463da4d"]}}};
